  /**
   * @method
   * @name sxbet#fetchMarkets
   * @description retrieves data on all active markets, each becomes one market
   * with its two sides listed under the outcomes key
   * @see https://docs.sx.bet/api-reference/get-markets-active
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.limit] max number of markets to collect (defaults to
   * options.marketsPageSize * options.maxMarketsPages, 5000)
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any rest =
                     this->omit(params, ccxt::list{std::string("limit")});
                 ccxt::any userLimit =
                     this->safeInteger(params, std::string("limit"));
                 ccxt::any rawMarkets =
                     awaitValue(this->fetchRawMarketsPaged(rest, userLimit));
                 ccxt::any markets = ccxt::list{};
                 ccxt::any rawMarketsLength = getArrayLength(rawMarkets);
                 for (ccxt::any i = 0; isLessThan(i, rawMarketsLength);
                      postFixIncrement(i)) {
                   arrayPush(markets,
                             this->parseSxbetMarket(::getValue(rawMarkets, i)));
                 }
                 ccxt::any marketsLength = getArrayLength(markets);
                 if (isTrue(
                         isTrue((!isEqual(userLimit, ccxt::any{}))) &&
                         isTrue((isGreaterThan(marketsLength, userLimit))))) {
                   return this->arraySlice(markets, 0, userLimit);
                 }
                 return markets;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#fetchRawMarketsPaged
   * @description pages through GET /markets/active (cursor-based via
   * paginationKey/nextKey), stopping once options.maxMarketsPages pages or
   * userLimit raw markets have been collected
   * @param {object} [extra] extra request params merged into every page (e.g.
   * leagueId, sportId, sportXeventId)
   * @param {int} [userLimit] stop collecting once this many raw markets have
   * been gathered
   * @returns {object[]} the raw (unparsed) sx.bet market objects
   */
  virtual std::shared_future<ccxt::any>
  fetchRawMarketsPaged(ccxt::any extra = ccxt::dict{},
                       ccxt::any userLimit = ccxt::any{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any pageSize = this->safeInteger(
                     this->options, std::string("marketsPageSize"), 100);
                 ccxt::any maxPages = this->safeInteger(
                     this->options, std::string("maxMarketsPages"), 50);
                 ccxt::any rawMarkets = ccxt::list{};
                 ccxt::any paginationKey = ccxt::any{};
                 ccxt::any page = 0;
                 while (true) {
                   ccxt::any request = ccxt::dict{
                       {std::string("pageSize"), pageSize},
                   };
                   if (isTrue(!isEqual(paginationKey, ccxt::any{}))) {
                     ::setValue(request, std::string("paginationKey"),
                                paginationKey);
                   }
                   ccxt::any response =
                       awaitValue(this->sxbetPublicGetMarketsActive(
                           this->extend(request, extra)));
                   ccxt::any result = this->safeDict(
                       response, std::string("data"), ccxt::dict{});
                   ccxt::any pageMarkets = this->safeList(
                       result, std::string("markets"), ccxt::list{});
                   ccxt::any pageMarketsLength = getArrayLength(pageMarkets);
                   for (ccxt::any i = 0; isLessThan(i, pageMarketsLength);
                        postFixIncrement(i)) {
                     arrayPush(rawMarkets, ::getValue(pageMarkets, i));
                   }
                   paginationKey =
                       this->safeString(result, std::string("nextKey"));
                   page = this->sum(page, 1);
                   ccxt::any collectedLength = getArrayLength(rawMarkets);
                   if (isTrue(
                           isTrue(
                               isTrue(isTrue((isLessThan(pageMarketsLength,
                                                         pageSize))) ||
                                      isTrue((isGreaterThanOrEqual(
                                          page, maxPages)))) ||
                               isTrue((isEqual(paginationKey, ccxt::any{})))) ||
                           isTrue((isTrue((!isEqual(userLimit, ccxt::any{}))) &&
                                   isTrue((isGreaterThanOrEqual(
                                       collectedLength, userLimit))))))) {
                     break;
                   }
                 }
                 return rawMarkets;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#filterRawMarketsByFixture
   * @description keeps only the raw markets belonging to one fixture — the
   * venue's own sportXeventId filter on /markets/active is unreliable (observed
   * live returning every fixture), so the scope is enforced client-side
   * @param {object[]} rawMarkets the raw sx.bet market objects
   * @param {string} sportXeventId the fixture id to keep
   * @returns {object[]} the raw markets of that fixture only
   */
  virtual ccxt::any filterRawMarketsByFixture(ccxt::any rawMarkets,
                                              ccxt::any sportXeventId) {
    ccxt::any result = ccxt::list{};
    ccxt::any rawMarketsLength = getArrayLength(rawMarkets);
    for (ccxt::any i = 0; isLessThan(i, rawMarketsLength);
         postFixIncrement(i)) {
      ccxt::any raw = ::getValue(rawMarkets, i);
      if (isTrue(isEqual(this->safeString(raw, std::string("sportXeventId")),
                         sportXeventId))) {
        arrayPush(result, raw);
      }
    }
    return result;
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetMarket
   * @description converts a single raw sx.bet market into one ccxt market whose
   * two sides become the outcomes
   * @param {object} raw the raw sx.bet market object
   * @returns {object} a [market
   * structure](https://docs.ccxt.com/#/?id=market-structure)
   */
  virtual ccxt::any parseSxbetMarket(ccxt::any raw) {
    //
    //     {
    //         "status": "ACTIVE",
    //         "marketHash":
    //         "0x7154aa3580267e276cccd0f4f826464a05e3efd8e1c81d7717bef6b5ae88b07d",
    //         "outcomeOneName": "Los Angeles Rams",
    //         "outcomeTwoName": "San Francisco 49ers",
    //         "outcomeVoidName": "NO_CONTEST",
    //         "teamOneName": "Los Angeles Rams",
    //         "teamTwoName": "San Francisco 49ers",
    //         "type": 226,
    //         "gameTime": 1789086900,
    //         "line": -2.5, // present on spread/total markets only
    //         "sportXeventId": "L18870109",
    //         "liveEnabled": true,
    //         "sportLabel": "Football",
    //         "sportId": 8,
    //         "leagueId": 243,
    //         "leagueLabel": "NFL",
    //         "mainLine": true,
    //         "isQuarterLineMarket": false
    //     }
    //
    ccxt::any marketHash =
        this->safeString(raw, std::string("marketHash"), std::string(""));
    ccxt::any teamOneName = this->safeString(raw, std::string("teamOneName"));
    ccxt::any teamTwoName = this->safeString(raw, std::string("teamTwoName"));
    ccxt::any outcomeOneName =
        this->safeString(raw, std::string("outcomeOneName"));
    ccxt::any outcomeTwoName =
        this->safeString(raw, std::string("outcomeTwoName"));
    ccxt::any eventSlug =
        this->shortenSlug(add(add(teamOneName, std::string(" ")), teamTwoName));
    // one fixture carries many markets (moneyline, several spread/total lines,
    // quarter/half variants) whose outcomeOneName text can coincide or nearly
    // coincide, so a text-only slug isn't guaranteed unique. suffix with the
    // market hash instead (always unique, letters+digits only so it survives
    // shortenSlug in one atomic word) parseToInt-wrapped .length: the bare
    // `const n = str.length;` statement is the php transpiler's ARRAY hint
    // (count()), which breaks on a string — this form emits strlen()/len()
    // correctly in both python and php
    ccxt::any hashLength = this->parseToInt(getStringLength(marketHash));
    ccxt::any hashSuffix =
        slice(marketHash, subtract(hashLength, 6), ccxt::any{});
    ccxt::any marketSlug = add(
        add(this->shortenSlug(outcomeOneName), std::string("_")), hashSuffix);
    ccxt::any marketSymbol = this->slugToMarketSymbol(eventSlug, marketSlug);
    ccxt::any status = this->safeStringUpper(raw, std::string("status"));
    ccxt::any active = (isEqual(status, std::string("ACTIVE")));
    // guard against a zero sentinel for "no scheduled game time" -
    // safeTimestamp would turn it into the 1970 epoch
    ccxt::any gameTime = ccxt::any{};
    if (isTrue(
            !isEqual(this->safeInteger(raw, std::string("gameTime"), 0), 0))) {
      gameTime = this->safeTimestamp(raw, std::string("gameTime"));
    }
    ccxt::any outcomeLabels = ccxt::list{outcomeOneName, outcomeTwoName};
    ccxt::any outcomeIds =
        ccxt::list{marketHash, add(marketHash, std::string("-2"))};
    ccxt::any outcomes = ccxt::list{};
    for (ccxt::any oi = 0; isLessThan(oi, getArrayLength(outcomeLabels));
         postFixIncrement(oi)) {
      ccxt::any label = ::getValue(outcomeLabels, oi);
      ccxt::any outcomeHandle =
          this->slugToOutcomeSymbol(eventSlug, marketSlug, label);
      arrayPush(outcomes,
                ccxt::dict{
                    {std::string("id"), ::getValue(outcomeIds, oi)},
                    {std::string("outcomeId"), ::getValue(outcomeIds, oi)},
                    {std::string("outcome"), outcomeHandle},
                    {std::string("market"), marketSymbol},
                    {std::string("label"), label},
                    {std::string("active"), active},
                    {std::string("winner"), ccxt::any{}},
                    {std::string("settleFraction"), ccxt::any{}},
                    {std::string("info"), raw},
                });
    }
    return ccxt::dict{
        {std::string("id"), marketHash},
        {std::string("market"), marketSymbol},
        {std::string("base"), std::string("USDC")},
        {std::string("quote"), std::string("USDC")},
        {std::string("settle"), ccxt::any{}},
        {std::string("baseId"), marketHash},
        {std::string("quoteId"), std::string("USDC")},
        {std::string("settleId"), ccxt::any{}},
        {std::string("type"), std::string("prediction")},
        {std::string("marketType"), std::string("binary")},
        {std::string("executionModel"), std::string("clob")},
        {std::string("spot"), false},
        {std::string("margin"), false},
        {std::string("swap"), false},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("prediction"), true},
        {std::string("active"), active},
        {std::string("resolved"), false},
        {std::string("resolvedOutcome"), ccxt::any{}},
        {std::string("contract"), false},
        {std::string("linear"), ccxt::any{}},
        {std::string("inverse"), ccxt::any{}},
        {std::string("contractSize"), ccxt::any{}},
        {std::string("expiry"), gameTime},
        {std::string("expiryDatetime"), this->iso8601(gameTime)},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("taker"), 0},
        {std::string("maker"), 0},
        {std::string("percentage"), true},
        {std::string("tierBased"), false},
        {std::string("feeSide"), std::string("get")},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"), 0.000001},
             {std::string("price"), 0.00125},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), 1},
                  {std::string("max"), 1},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), 1},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), 0},
                  {std::string("max"), 1},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"), 1},
                  {std::string("max"), ccxt::any{}},
              }},
         }},
        {std::string("outcomes"), outcomes},
        {std::string("info"), raw},
        {std::string("created"), ccxt::any{}},
    };
  }

  /**
   * @method
   * @name sxbet#fetchEvents
   * @description fetches sx.bet fixtures (one fixture = one event, its markets
   * are every moneyline/spread/total line on that fixture) scoped by eventId,
   * leagueId, sportId or a free-text query/tags match against team and league
   * names — always live from the API, never the local cache (it POPULATES the
   * cache for later event()/outcome lookups). query/queries/tags are matched
   * client-side over a bounded scan of /markets/active — the venue's GET
   * /search covers team names only (not league or sport labels) and is not
   * wired here yet
   * @see https://docs.sx.bet/api-reference/get-markets-active
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.eventId] direct lookup by unified event id (the
   * sx.bet sportXeventId, e.g. 'L18870109')
   * @param {string} [params.query] free-text search matched against team and
   * league names
   * @param {string[]} [params.queries] multiple free-text searches (alternative
   * to query, unioned)
   * @param {string[]} [params.tags] matched identically to query/queries
   * (sx.bet has no tag taxonomy)
   * @param {int} [params.leagueId] sx.bet league id (e.g. 243 for NFL) —
   * fetched server-side
   * @param {int} [params.sportId] sx.bet sport id (e.g. 8 for Football) —
   * fetched server-side
   * @param {string} [params.status] 'active' | 'inactive' | 'closed' | 'all'
   * @param {int} [params.limit] max number of events to return
   * @returns {object[]} an array of event structures
   */
  std::shared_future<ccxt::any>
  fetchEvents(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->requireEventQuery(params);
                 ccxt::any eventId = this->safeString2(
                     params, std::string("eventId"), std::string("slug"));
                 ccxt::any leagueId =
                     this->safeString(params, std::string("leagueId"));
                 ccxt::any sportId =
                     this->safeString(params, std::string("sportId"));
                 ccxt::any queries = this->parseSearchQueries(params);
                 ccxt::any tags =
                     this->safeList(params, std::string("tags"), ccxt::list{});
                 ccxt::any tagsLength = getArrayLength(tags);
                 for (ccxt::any i = 0; isLessThan(i, tagsLength);
                      postFixIncrement(i)) {
                   arrayPush(queries, ::getValue(tags, i));
                 }
                 ccxt::any rest = this->omit(
                     params,
                     ccxt::list{std::string("eventId"), std::string("slug"),
                                std::string("leagueId"), std::string("sportId"),
                                std::string("query"), std::string("queries"),
                                std::string("tags"), std::string("status"),
                                std::string("sort"), std::string("searchIn"),
                                std::string("limit")});
                 ccxt::any rawMarkets = ccxt::any{};
                 if (isTrue(!isEqual(eventId, ccxt::any{}))) {
                   rawMarkets = awaitValue(this->fetchRawMarketsPaged(
                       this->extend(
                           ccxt::dict{
                               {std::string("sportXeventId"), eventId},
                           },
                           rest),
                       ccxt::any{}));
                   // the venue's sportXeventId filter on /markets/active is
                   // unreliable (observed live returning every fixture) —
                   // enforce the scope client-side
                   rawMarkets =
                       this->filterRawMarketsByFixture(rawMarkets, eventId);
                 } else if (isTrue(!isEqual(leagueId, ccxt::any{}))) {
                   rawMarkets = awaitValue(this->fetchRawMarketsPaged(
                       this->extend(
                           ccxt::dict{
                               {std::string("leagueId"), leagueId},
                           },
                           rest),
                       ccxt::any{}));
                 } else if (isTrue(!isEqual(sportId, ccxt::any{}))) {
                   rawMarkets = awaitValue(this->fetchRawMarketsPaged(
                       this->extend(
                           ccxt::dict{
                               {std::string("sportId"), sportId},
                           },
                           rest),
                       ccxt::any{}));
                 } else {
                   // no server-side scope left, only query/tags — full scan
                   // honoring the fetchMarkets bound, then filter client-side
                   // (the venue's /search covers team names only)
                   rawMarkets = awaitValue(
                       this->fetchRawMarketsPaged(rest, ccxt::any{}));
                 }
                 ccxt::any queriesLength = getArrayLength(queries);
                 if (isTrue(isGreaterThan(queriesLength, 0))) {
                   ccxt::any filtered = ccxt::list{};
                   ccxt::any preFilterLength = getArrayLength(rawMarkets);
                   for (ccxt::any i = 0; isLessThan(i, preFilterLength);
                        postFixIncrement(i)) {
                     if (isTrue(this->matchesEventQuery(
                             ::getValue(rawMarkets, i), queries))) {
                       arrayPush(filtered, ::getValue(rawMarkets, i));
                     }
                   }
                   rawMarkets = filtered;
                 }
                 ccxt::any grouped = ccxt::dict{};
                 ccxt::any order = ccxt::list{};
                 ccxt::any rawMarketsLength = getArrayLength(rawMarkets);
                 for (ccxt::any i = 0; isLessThan(i, rawMarketsLength);
                      postFixIncrement(i)) {
                   ccxt::any raw = ::getValue(rawMarkets, i);
                   ccxt::any sportXeventId =
                       this->safeString(raw, std::string("sportXeventId"));
                   if (isTrue(isEqual(sportXeventId, ccxt::any{}))) {
                     continue;
                   }
                   if (!isTrue((inOp(grouped, sportXeventId)))) {
                     ::setValue(grouped, sportXeventId, ccxt::list{});
                     arrayPush(order, sportXeventId);
                   }
                   arrayPush(::getValue(grouped, sportXeventId), raw);
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   this->markets = this->createSafeDictionary();
                 }
                 ccxt::any result = ccxt::list{};
                 ccxt::any orderLength = getArrayLength(order);
                 for (ccxt::any i = 0; isLessThan(i, orderLength);
                      postFixIncrement(i)) {
                   ccxt::any fixtureId = ::getValue(order, i);
                   ccxt::any event = this->parseEvent(
                       fixtureId, ::getValue(grouped, fixtureId));
                   ccxt::any evMarkets = this->safeList(
                       event, std::string("markets"), ccxt::list{});
                   ccxt::any evMarketsLength = getArrayLength(evMarkets);
                   for (ccxt::any j = 0; isLessThan(j, evMarketsLength);
                        postFixIncrement(j)) {
                     ccxt::any m = ::getValue(evMarkets, j);
                     ::setValue(this->markets,
                                ::getValue(m, std::string("market")), m);
                   }
                   arrayPush(result, event);
                 }
                 this->populateOutcomes();
                 this->setEvents(result);
                 ccxt::any postParams = this->omit(
                     params,
                     ccxt::list{std::string("leagueId"), std::string("sportId"),
                                std::string("query"), std::string("queries"),
                                std::string("tags")});
                 return this->applyEventFetchParams(result, postParams,
                                                    ccxt::list{});
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchEvent
   * @description fetches a single sx.bet fixture (event) by its sportXeventId
   * @see https://docs.sx.bet/api-reference/get-markets-active
   * @param {string} id the sx.bet sportXeventId, e.g. 'L18870109'
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction event
   * structure](https://docs.ccxt.com/#/?id=prediction-event-structure)
   */
  std::shared_future<ccxt::any>
  fetchEvent(ccxt::any id, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any rawMarkets = awaitValue(this->fetchRawMarketsPaged(
                     this->extend(
                         ccxt::dict{
                             {std::string("sportXeventId"), id},
                         },
                         params),
                     ccxt::any{}));
                 // enforce the fixture scope client-side — see
                 // filterRawMarketsByFixture
                 rawMarkets = this->filterRawMarketsByFixture(rawMarkets, id);
                 ccxt::any rawMarketsLength = getArrayLength(rawMarkets);
                 if (isTrue(isEqual(rawMarketsLength, 0))) {
                   throw BadSymbol(toString(add(
                       add(this->id, std::string(" fetchEvent() could not find "
                                                 "an active fixture ")),
                       id)));
                 }
                 ccxt::any event = this->parseEvent(id, rawMarkets);
                 this->indexEventOutcomes(event);
                 this->setEvents(ccxt::list{event});
                 return event;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#matchesEventQuery
   * @description checks a raw market's team/league names against a list of
   * free-text queries, matching in either direction (a short user query inside
   * a long name, or — since fetchEvents derives its fallback test query from an
   * already-slugified handle — a long joined query containing a short name)
   * @param {object} raw the raw sx.bet market object
   * @param {string[]} queries lowercase-insensitive free-text queries
   * @returns {boolean} whether any query matches any of the market's
   * team/league/outcome names
   */
  virtual ccxt::any matchesEventQuery(ccxt::any raw, ccxt::any queries) {
    ccxt::any fields =
        ccxt::list{this->safeString(raw, std::string("teamOneName")),
                   this->safeString(raw, std::string("teamTwoName")),
                   this->safeString(raw, std::string("leagueLabel")),
                   this->safeString(raw, std::string("sportLabel")),
                   this->safeString(raw, std::string("outcomeOneName")),
                   this->safeString(raw, std::string("outcomeTwoName"))};
    ccxt::any queriesLength = getArrayLength(queries);
    for (ccxt::any qi = 0; isLessThan(qi, queriesLength);
         postFixIncrement(qi)) {
      ccxt::any query = toLowerCase(::getValue(queries, qi));
      if (isTrue(isEqual(query, std::string("")))) {
        continue;
      }
      for (ccxt::any fi = 0; isLessThan(fi, getArrayLength(fields));
           postFixIncrement(fi)) {
        ccxt::any field = ::getValue(fields, fi);
        if (isTrue(isEqual(field, ccxt::any{}))) {
          continue;
        }
        ccxt::any fieldLower = toLowerCase(field);
        if (isTrue(isTrue((isGreaterThanOrEqual(getIndexOf(query, fieldLower),
                                                0))) ||
                   isTrue((isGreaterThanOrEqual(getIndexOf(fieldLower, query),
                                                0))))) {
          return true;
        }
      }
    }
    return false;
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseEvent
   * @description groups a fixture's raw markets (all sharing one sportXeventId)
   * into one unified event structure
   * @param {string} fixtureId the sx.bet sportXeventId
   * @param {object[]} rawMarkets the raw sx.bet market objects belonging to
   * this fixture
   * @returns {object} an event structure
   */
  virtual ccxt::any parseEvent(ccxt::any fixtureId, ccxt::any rawMarkets) {
    ccxt::any marketsList = ccxt::list{};
    ccxt::any anyActive = false;
    ccxt::any earliestGameTime = ccxt::any{};
    ccxt::any teamOneName = ccxt::any{};
    ccxt::any teamTwoName = ccxt::any{};
    ccxt::any leagueLabel = ccxt::any{};
    ccxt::any rawMarketsLength = getArrayLength(rawMarkets);
    for (ccxt::any i = 0; isLessThan(i, rawMarketsLength);
         postFixIncrement(i)) {
      ccxt::any raw = ::getValue(rawMarkets, i);
      ccxt::any parsed = this->parseSxbetMarket(raw);
      if (isTrue(isEqual(parsed, ccxt::any{}))) {
        throw ExchangeError(toString(
            add(this->id,
                std::string(" parseEvent() could not resolve parsed market"))));
      }
      arrayPush(marketsList, parsed);
      if (isTrue(isEqual(::getValue(parsed, std::string("active")), true))) {
        anyActive = true;
      }
      if (isTrue(isEqual(teamOneName, ccxt::any{}))) {
        teamOneName = this->safeString(raw, std::string("teamOneName"));
        teamTwoName = this->safeString(raw, std::string("teamTwoName"));
        leagueLabel = this->safeString(raw, std::string("leagueLabel"));
      }
      ccxt::any gameTime = this->safeString(raw, std::string("gameTime"));
      // skip the zero sentinel for "no scheduled game time" so it can't become
      // the epoch
      if (isTrue(isTrue(isTrue((!isEqual(gameTime, ccxt::any{}))) &&
                        isTrue((!isEqual(gameTime, std::string("0"))))) &&
                 isTrue((isTrue((isEqual(earliestGameTime, ccxt::any{}))) ||
                         isTrue((isLessThan(gameTime, earliestGameTime))))))) {
        earliestGameTime = gameTime;
      }
    }
    ccxt::any end = this->safeTimestamp(
        ccxt::dict{
            {std::string("gameTime"), earliestGameTime},
        },
        std::string("gameTime"));
    // some fixtures carry no team names on their market rows - fall back to the
    // fixture id so the unified event handle is never empty or built from
    // stringified nulls
    ccxt::any title = ccxt::any{};
    ccxt::any eventSlug = ccxt::any{};
    if (isTrue(isTrue((!isEqual(teamOneName, ccxt::any{}))) &&
               isTrue((!isEqual(teamTwoName, ccxt::any{}))))) {
      title = add(add(teamOneName, std::string(" vs ")), teamTwoName);
      eventSlug = this->shortenSlug(
          add(add(teamOneName, std::string(" ")), teamTwoName));
    } else {
      eventSlug = this->shortenSlug(fixtureId);
    }
    return ccxt::dict{
        {std::string("id"), fixtureId},
        {std::string("slug"), fixtureId},
        {std::string("event"), eventSlug},
        {std::string("title"), title},
        {std::string("description"), ccxt::any{}},
        {std::string("category"), leagueLabel},
        {std::string("tags"), ccxt::any{}},
        {std::string("markets"), marketsList},
        {std::string("mutuallyExclusive"), false},
        {std::string("active"), anyActive},
        {std::string("resolved"), ccxt::any{}},
        {std::string("volume"), ccxt::any{}},
        {std::string("liquidity"), ccxt::any{}},
        {std::string("created"), ccxt::any{}},
        {std::string("createdDatetime"), ccxt::any{}},
        {std::string("end"), end},
        {std::string("endDatetime"), this->iso8601(end)},
        {std::string("image"), ccxt::any{}},
        {std::string("url"), ccxt::any{}},
        {std::string("info"), rawMarkets},
    };
  }

  /**
   * @ignore
   * @method
   * @name sxbet#loadSxObv3Metadata
   * @description fetches and caches GET /metadata/obv3 - the v3 orderbook
   * metadata carrying the ready-made EIP-712 domain, the active base asset and
   * the order size limits
   * @see https://docs.sx.bet/api-reference/get-metadata-obv3
   * @returns {object} the cached obv3 metadata data object
   */
  virtual std::shared_future<ccxt::any> loadSxObv3Metadata() {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any cached = this->safeDict(
                            this->options, std::string("sxObv3Metadata"));
                        if (isTrue(!isEqual(cached, ccxt::any{}))) {
                          return cached;
                        }
                        ccxt::any response =
                            awaitValue(this->sxbetPublicGetMetadataObv3());
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        ::setValue(this->options, std::string("sxObv3Metadata"),
                                   data);
                        return data;
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#roundOddsToLadder
   * @description rounds an implied probability (0-1) to sx.bet's odds ladder
   * (oddsLadderStepSize is in units of 1e-5, e.g. 125 -> a 0.125% step) — a
   * maker's percentageOdds is rejected unless it lands exactly on the ladder
   * @param {string} probability the implied probability in decimal-string form
   * (0-1)
   * @param {string} oddsLadderStepSize the raw oddsLadderStepSize from
   * /metadata/obv3 (e.g. '125')
   * @returns {string} the probability rounded to the nearest ladder step, in
   * decimal-string form
   */
  virtual ccxt::any roundOddsToLadder(ccxt::any probability,
                                      ccxt::any oddsLadderStepSize) {
    ccxt::any tickSize =
        ccxt::Precise::stringDiv(oddsLadderStepSize, std::string("100000"), 10);
    return this->decimalToPrecision(probability, ROUND, tickSize, TICK_SIZE);
  }

  /**
   * @ignore
   * @method
   * @name sxbet#hashEip712Digest
   * @description hashes an EIP-712 encoded payload (domainSeparator‖structHash,
   * prefixed with 0x1901 by ethEncodeStructuredData) down to the final 32-byte
   * digest to sign, used by sx.bet's taker-fill and cancel signatures
   * @param {Uint8Array} encoded the output of this.ethEncodeStructuredData
   * (domain, types, message)
   * @returns {string} the 32-byte digest to ecdsa-sign, in '0x'-prefixed hex
   * form
   */
  virtual ccxt::any hashEip712Digest(ccxt::any encoded) {
    return add(std::string("0x"),
               this->hash(encoded, keccak, std::string("hex")));
  }

  /**
   * @ignore
   * @method
   * @name sxbet#signDigest
   * @description ecdsa-signs a 32-byte digest and assembles the r‖s‖v hex
   * signature sx.bet expects
   * @param {string} digest the '0x'-prefixed 32-byte digest to sign
   * @param {string} privateKey the signer's private key
   * @returns {string} a '0x'-prefixed 65-byte hex signature (r‖s‖v)
   */
  virtual ccxt::any signDigest(ccxt::any digest, ccxt::any privateKey) {
    ccxt::any signature =
        ecdsa(slice(digest, -64, ccxt::any{}),
              slice(privateKey, -64, ccxt::any{}), secp256k1, ccxt::any{});
    // assign to bare locals before padStart — the php transpiler's str_pad
    // regex only matches a simple identifier, an expression form leaks a raw
    // padStart() call
    ccxt::any rRaw = ::getValue(signature, std::string("r"));
    ccxt::any sRaw = ::getValue(signature, std::string("s"));
    ccxt::any r = padStart(rRaw, 64, std::string("0"));
    ccxt::any s = padStart(sRaw, 64, std::string("0"));
    ccxt::any v = this->intToBase16(
        this->sum(27, ::getValue(signature, std::string("v"))));
    return add(add(add(std::string("0x"), r), s), v);
  }

  /**
   * @ignore
   * @method
   * @name sxbet#fetchErc20Name
   * @description reads an ERC20 token's name() via eth_call (needed for the
   * Permit EIP-712 domain — must match the token's real on-chain name or the
   * signature fails verification)
   * @param {string} rpcUrl the RPC endpoint to call
   * @param {string} tokenAddress the token contract address
   * @returns {string} the token's on-chain name
   */
  virtual std::shared_future<ccxt::any> fetchErc20Name(ccxt::any rpcUrl,
                                                       ccxt::any tokenAddress) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any nameCallData =
                            std::string("0x06fdde03"); // name()
                        ccxt::any result = awaitValue(this->ethRpc(
                            rpcUrl, std::string("eth_call"),
                            ccxt::list{ccxt::dict{
                                           {std::string("to"), tokenAddress},
                                           {std::string("data"), nameCallData},
                                       },
                                       std::string("latest")}));
                        ccxt::any hex = this->remove0xPrefix(result);
                        // dynamic ABI string return: [32-byte offset][32-byte
                        // length][utf8 bytes, right-padded]
                        ccxt::any lengthHex = slice(hex, 64, 128);
                        ccxt::any length = this->hexToInt(lengthHex);
                        ccxt::any dataEnd = this->sum(128, multiply(length, 2));
                        ccxt::any dataHex = slice(hex, 128, dataEnd);
                        return this->decode(this->base16ToBinary(dataHex));
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#hexToInt
   * @description parses a hex string (no '0x' prefix) into an integer — plain
   * digit-by-digit, since JS's parseInt (hex, 16) two-argument form has no
   * portable equivalent across languages/transpilers. Only used for small
   * values (byte lengths, permit nonces), safe well within the float-precision
   * range
   * @param {string} hex the hex string, no '0x' prefix
   * @returns {int} the parsed integer
   */
  virtual ccxt::any hexToInt(ccxt::any hex) {
    ccxt::any digits = std::string("0123456789abcdef");
    ccxt::any lowerHex = toLowerCase(hex);
    ccxt::any hexLength = getStringLength(lowerHex);
    ccxt::any result = 0;
    for (ccxt::any i = 0; isLessThan(i, hexLength); postFixIncrement(i)) {
      ccxt::any ch = ::getValue(lowerHex, i);
      ccxt::any digitValue = getIndexOf(digits, ch);
      result = add((multiply(result, 16)), digitValue);
    }
    return result;
  }

  /**
   * @ignore
   * @method
   * @name sxbet#fetchSxbetProxy
   * @description fetches the account's obv3 proxy wallet state
   * @see https://docs.sx.bet/api-reference/get-user-proxy
   * @returns {object} the raw proxy data ({obv3ProxyWalletAddress, deployed,
   * multisigSafeAddress})
   */
  virtual std::shared_future<ccxt::any> fetchSxbetProxy() {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response =
                            awaitValue(this->sxbetPrivateGetUserProxy());
                        return this->safeDict(response, std::string("data"),
                                              ccxt::dict{});
                      })
        .share();
  }

  /**
   * @method
   * @name sxbet#approve
   * @description funds the account's obv3 proxy wallet - v3 trading capital
   * must sit inside the proxy. Deploys the proxy first when absent, then moves
   * USDC from the wallet into it via a gasless EIP-2612 Permit signature (POST
   * /user/transfer-to-proxy)
   * @see https://docs.sx.bet/api-reference/post-user-transfer-to-proxy
   * @see https://docs.sx.bet/api-reference/post-user-deploy-proxy
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.amount] the USDC amount to move into the proxy
   * (required)
   * @param {string} [params.tokenAddress] the token to transfer, defaults to
   * the active base token
   * @param {string} [params.spender] the transfer executor granted the permit,
   * defaults to options.transferToProxySpender or the obv3
   * transferToProxyExecutorAddress
   * @param {int} [params.deadline] unix seconds the permit signature expires
   * at, defaults to options.approveDeadlineSeconds from now
   * @param {string} [params.rpcUrl] overrides the chain's default RPC endpoint
   * (see options.chains)
   * @returns {object} a dict with the raw response and the transfer sessionId
   */
  virtual std::shared_future<ccxt::any>
  approve(ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 ccxt::any amount =
                     this->safeNumber(params, std::string("amount"));
                 if (isTrue(isEqual(amount, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " approve() requires params.amount - the USDC "
                               "amount to move into the proxy wallet"))));
                 }
                 ccxt::any proxy = awaitValue(this->fetchSxbetProxy());
                 ccxt::any deployed =
                     this->safeBool(proxy, std::string("deployed"), false);
                 if (isTrue(!isEqual(deployed, true))) {
                   awaitValue(this->sxbetPrivatePostUserDeployProxy());
                   // deployment is asynchronous - poll until the proxy exists
                   for (ccxt::any i = 0; isLessThan(i, 30);
                        postFixIncrement(i)) {
                     awaitValue(this->sleep(2000));
                     ccxt::any state = awaitValue(this->fetchSxbetProxy());
                     if (isTrue(this->safeBool(state, std::string("deployed"),
                                               false))) {
                       break;
                     }
                   }
                 }
                 ccxt::any obv3 = awaitValue(this->loadSxObv3Metadata());
                 ccxt::any activeAsset = this->safeDict(
                     obv3, std::string("activeAsset"), ccxt::dict{});
                 ccxt::any chainId =
                     this->safeInteger(obv3, std::string("chainId"));
                 ccxt::any usdcAddress =
                     this->safeString(activeAsset, std::string("baseToken"));
                 // the permit spender is the venue's transfer-to-proxy
                 // executor, published in /metadata/obv3
                 ccxt::any executorAddress = this->safeString(
                     obv3, std::string("transferToProxyExecutorAddress"));
                 ccxt::any tokenAddress = this->safeString(
                     params, std::string("tokenAddress"), usdcAddress);
                 if (isTrue(isEqual(tokenAddress, ccxt::any{}))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" approve() could not resolve the base "
                                       "token address from /metadata/obv3"))));
                 }
                 ccxt::any spenderparamsSpenderVariable =
                     this->handleOptionStringAndParams2(
                         params, std::string("approve"), std::string("spender"),
                         std::string("transferToProxySpender"),
                         executorAddress);
                 ccxt::any spender =
                     ::getValue(spenderparamsSpenderVariable, 0);
                 ccxt::any paramsSpender =
                     ::getValue(spenderparamsSpenderVariable, 1);
                 if (isTrue(isEqual(spender, ccxt::any{}))) {
                   throw BadRequest(toString(add(
                       this->id,
                       std::string(" approve() could not resolve the "
                                   "transfer-to-proxy executor from "
                                   "/metadata/obv3 - pass params.spender"))));
                 }
                 ccxt::any chains = this->safeDict(
                     this->options, std::string("chains"), ccxt::dict{});
                 ccxt::any chainConfig = this->safeDict(
                     chains, this->numberToString(chainId), ccxt::dict{});
                 ccxt::any rpcUrl = this->safeString(
                     paramsSpender, std::string("rpcUrl"),
                     this->safeString(chainConfig, std::string("rpcUrl")));
                 if (isTrue(isEqual(rpcUrl, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(add(add(this->id,
                                   std::string(" approve() has no RPC endpoint "
                                               "configured for chainId ")),
                               this->numberToString(chainId)),
                           std::string(" - pass params.rpcUrl"))));
                 }
                 ccxt::any owner = this->walletAddress;
                 ccxt::any nonceCallData =
                     add(std::string("0x7ecebe00"),
                         this->padHexAddress(owner)); // nonces(address)
                 ccxt::any nonceResult = awaitValue(this->ethRpc(
                     rpcUrl, std::string("eth_call"),
                     ccxt::list{ccxt::dict{
                                    {std::string("to"), tokenAddress},
                                    {std::string("data"), nonceCallData},
                                },
                                std::string("latest")}));
                 ccxt::any nonceHex = this->hexToRlpBytes(nonceResult);
                 ccxt::any nonce = (isTrue((isEqual(nonceHex, std::string(""))))
                                        ? ccxt::any(std::string("0"))
                                        : ccxt::any(this->numberToString(
                                              this->hexToInt(nonceHex))));
                 ccxt::any tokenName =
                     awaitValue(this->fetchErc20Name(rpcUrl, tokenAddress));
                 ccxt::any defaultDeadlineSeconds = this->safeInteger(
                     this->options, std::string("approveDeadlineSeconds"),
                     7200);
                 ccxt::any deadline = this->safeInteger(
                     paramsSpender, std::string("deadline"),
                     this->sum(this->seconds(), defaultDeadlineSeconds));
                 ccxt::any value = this->decimalToPrecision(
                     ccxt::Precise::stringMul(this->numberToString(amount),
                                              std::string("1000000")),
                     ROUND, 0, DECIMAL_PLACES);
                 ccxt::any domain = ccxt::dict{
                     {std::string("name"), tokenName},
                     {std::string("version"), std::string("1")},
                     {std::string("chainId"), chainId},
                     {std::string("verifyingContract"), tokenAddress},
                 };
                 ccxt::any messageTypes = ccxt::dict{
                     {std::string("Permit"),
                      ccxt::list{
                          ccxt::dict{
                              {std::string("name"), std::string("owner")},
                              {std::string("type"), std::string("address")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("spender")},
                              {std::string("type"), std::string("address")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("value")},
                              {std::string("type"), std::string("uint256")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("nonce")},
                              {std::string("type"), std::string("uint256")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("deadline")},
                              {std::string("type"), std::string("uint256")},
                          }}},
                 };
                 ccxt::any messageData = ccxt::dict{
                     {std::string("owner"), owner},
                     {std::string("spender"), spender},
                     {std::string("value"), value},
                     {std::string("nonce"), nonce},
                     {std::string("deadline"), deadline},
                 };
                 ccxt::any encoded = this->ethEncodeStructuredData(
                     domain, messageTypes, messageData);
                 ccxt::any digest = this->hashEip712Digest(encoded);
                 ccxt::any signature =
                     this->signDigest(digest, this->privateKey);
                 ccxt::any request = ccxt::dict{
                     {std::string("owner"), owner},
                     {std::string("spender"), spender},
                     {std::string("tokenAddress"), tokenAddress},
                     {std::string("value"), value},
                     {std::string("deadline"), this->numberToString(deadline)},
                     {std::string("signature"), signature},
                 };
                 ccxt::any rest = this->omit(
                     paramsSpender, ccxt::list{std::string("amount"),
                                               std::string("tokenAddress"),
                                               std::string("deadline"),
                                               std::string("rpcUrl")});
                 ccxt::any response =
                     awaitValue(this->sxbetPrivatePostUserTransferToProxy(
                         this->extend(request, rest)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 return ccxt::dict{
                     {std::string("info"), response},
                     {std::string("id"),
                      this->safeString(data, std::string("sessionId"))},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#createOrder
   * @description places an order on sx.bet's v3 unified orderbook - a 'limit'
   * order rests with GTC time-in-force, a 'market' order fills immediately with
   * IOC (or FOK via params.timeInForce). sx.bet has no shares - 'amount' is the
   * USDC stake to risk, and 'price' is the implied probability (0-1) of the
   * requested outcome. 'sell' bets the OPPOSITE outcome of the one requested
   * (sx.bet is bilateral: there is no owned position to sell, only the
   * complementary side of the same market)
   * @see https://docs.sx.bet/api-reference/post-orders-v3
   * @param {string} outcome unified outcome or outcome token id
   * @param {string} type 'limit' (GTC resting order) or 'market' (IOC immediate
   * fill)
   * @param {string} side 'buy' backs the requested outcome, 'sell' backs the
   * complementary one
   * @param {float} amount the USDC amount to stake/risk
   * @param {float} [price] implied probability (0-1) of the requested outcome;
   * required for both order types
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.timeInForce] overrides the derived value - 'GTC',
   * 'IOC' or 'FOK'
   * @param {int} [params.expiry] unix seconds the order expires at; must be in
   * the future (zero and past values are rejected, so is anything inside the
   * fixture's betting-delay window - /metadata/obv3 resolves the delay per
   * sport/league, live vs pregame), defaults to
   * options.defaultOrderExpirySeconds from now
   * @param {string} [params.salt] overrides the random salt differentiating
   * this order
   * @param {string} [params.clientOrderId] caller-chosen id echoed back on
   * reads (max 64 chars)
   * @param {boolean} [params.waitForOutcome] wait for the matching outcome
   * inline (default true)
   * @param {boolean} [params.useBetCredits] fund the stake from bet credits
   * instead of the proxy balance (IOC/FOK only)
   * @param {string} [params.externalUserId] partner attribution id echoed back
   * on order, fill and trade reads
   * @returns {object} a [prediction order
   * structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any outcome, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 if (isTrue(isTrue((!isEqual(type, std::string("limit")))) &&
                            isTrue((!isEqual(type, std::string("market")))))) {
                   throw InvalidOrder(toString(add(
                       add(this->id, std::string(" createOrder() type must be "
                                                 "'limit' or 'market', got ")),
                       type)));
                 }
                 if (isTrue(isEqual(price, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " createOrder() requires a price - the implied "
                               "probability of the requested outcome"))));
                 }
                 // the venue has no post-only or trigger mechanics - reject the
                 // unified params instead of forwarding fields the exchange
                 // would silently ignore
                 ccxt::any postOnly =
                     this->safeBool(params, std::string("postOnly"), false);
                 if (isTrue(isEqual(postOnly, true))) {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(" createOrder() does not support postOnly - "
                                   "GTC orders may cross on entry"))));
                 }
                 ccxt::any triggerPrice = this->safeStringN(
                     params, ccxt::list{std::string("triggerPrice"),
                                        std::string("stopLossPrice"),
                                        std::string("takeProfitPrice")});
                 if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(" createOrder() does not support trigger, "
                                   "stop-loss or take-profit orders"))));
                 }
                 ccxt::any marketHash = this->safeString(
                     ::getValue(outcomeObj, std::string("info")),
                     std::string("marketHash"), std::string(""));
                 ccxt::any outcomeId =
                     this->safeString(outcomeObj, std::string("outcomeId"));
                 ccxt::any isOutcomeOne = (isEqual(outcomeId, marketHash));
                 ccxt::any isBuy = (isEqual(side, std::string("buy")));
                 // 'sell' bets the complementary outcome, mirroring the
                 // requested outcome's own probability - matches the
                 // normalize-to-one-book convention used by other prediction
                 // venues
                 ccxt::any isMakerBettingOutcomeOne =
                     (isTrue((isBuy)) ? ccxt::any(isOutcomeOne)
                                      : ccxt::any(!isTrue(isOutcomeOne)));
                 ccxt::any priceStr = this->numberToString(price);
                 ccxt::any probability =
                     (isTrue((isBuy)) ? ccxt::any(priceStr)
                                      : ccxt::any(ccxt::Precise::stringSub(
                                            std::string("1"), priceStr)));
                 ccxt::any obv3 = awaitValue(this->loadSxObv3Metadata());
                 ccxt::any domain =
                     this->safeDict(obv3, std::string("domain"), ccxt::dict{});
                 ccxt::any activeAsset = this->safeDict(
                     obv3, std::string("activeAsset"), ccxt::dict{});
                 ccxt::any baseToken =
                     this->safeString(activeAsset, std::string("baseToken"));
                 ccxt::any oddsLadderStepSize =
                     this->numberToString(this->safeInteger(
                         obv3, std::string("oddsLadderStepSize"), 125));
                 ccxt::any roundedProbability =
                     this->roundOddsToLadder(probability, oddsLadderStepSize);
                 ccxt::any percentageOdds = this->decimalToPrecision(
                     ccxt::Precise::stringMul(
                         roundedProbability,
                         std::string("100000000000000000000")),
                     ROUND, 0, DECIMAL_PLACES);
                 ccxt::any amountStr = this->numberToString(amount);
                 ccxt::any totalBetSize = this->decimalToPrecision(
                     ccxt::Precise::stringMul(amountStr,
                                              std::string("1000000")),
                     ROUND, 0, DECIMAL_PLACES);
                 ccxt::any saltNumber = this->safeString(
                     params, std::string("salt"),
                     this->numberToString(this->milliseconds()));
                 // the request body carries the salt in 32-byte-hex form; the
                 // signedFlag struct carries the same value in uint256 form -
                 // both parse to one number server-side. assign to bare locals
                 // before padStart - see the transpiler notes
                 ccxt::any saltHexRaw =
                     this->intToBase16(this->parseToInt(saltNumber));
                 ccxt::any saltHexPadded =
                     padStart(saltHexRaw, 64, std::string("0"));
                 ccxt::any saltHex = add(std::string("0x"), saltHexPadded);
                 ccxt::any defaultExpirySeconds = this->safeInteger(
                     this->options, std::string("defaultOrderExpirySeconds"),
                     86400);
                 ccxt::any expiry = this->safeInteger(
                     params, std::string("expiry"),
                     this->sum(this->seconds(), defaultExpirySeconds));
                 ccxt::any defaultTif = std::string("IOC");
                 if (isTrue(isEqual(type, std::string("limit")))) {
                   defaultTif = std::string("GTC");
                 }
                 ccxt::any timeInForceparamsTimeInForceVariable =
                     this->handleOptionStringAndParams(
                         params, std::string("createOrder"),
                         std::string("timeInForce"), defaultTif);
                 ccxt::any timeInForce =
                     ::getValue(timeInForceparamsTimeInForceVariable, 0);
                 ccxt::any paramsTimeInForce =
                     ::getValue(timeInForceparamsTimeInForceVariable, 1);
                 // an explicit IOC/FOK on a 'limit' order is honored verbatim -
                 // the venue executes exactly that time-in-force. only GTC on a
                 // 'market' order is refused: it would silently rest,
                 // contradicting the immediate-fill semantics the type promises
                 if (isTrue(
                         isTrue((isEqual(type, std::string("market")))) &&
                         isTrue((isEqual(timeInForce, std::string("GTC")))))) {
                   throw InvalidOrder(toString(add(
                       this->id,
                       std::string(" createOrder() market orders cannot be GTC "
                                   "- use type 'limit' for a resting order"))));
                 }
                 ccxt::any maker = this->walletAddress;
                 ccxt::any messageTypes = ccxt::dict{
                     {std::string("Order"),
                      ccxt::list{
                          ccxt::dict{
                              {std::string("name"), std::string("marketHash")},
                              {std::string("type"), std::string("bytes32")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("baseToken")},
                              {std::string("type"), std::string("address")},
                          },
                          ccxt::dict{
                              {std::string("name"),
                               std::string("totalBetSize")},
                              {std::string("type"), std::string("uint256")},
                          },
                          ccxt::dict{
                              {std::string("name"),
                               std::string("percentageOdds")},
                              {std::string("type"), std::string("uint256")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("salt")},
                              {std::string("type"), std::string("uint256")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("expiry")},
                              {std::string("type"), std::string("uint256")},
                          },
                          ccxt::dict{
                              {std::string("name"), std::string("maker")},
                              {std::string("type"), std::string("address")},
                          },
                          ccxt::dict{
                              {std::string("name"),
                               std::string("isMakerBettingOutcomeOne")},
                              {std::string("type"), std::string("bool")},
                          }}},
                 };
                 ccxt::any messageData = ccxt::dict{
                     {std::string("marketHash"), marketHash},
                     {std::string("baseToken"), baseToken},
                     {std::string("totalBetSize"), totalBetSize},
                     {std::string("percentageOdds"), percentageOdds},
                     {std::string("salt"), saltNumber},
                     {std::string("expiry"), expiry},
                     {std::string("maker"), maker},
                     {std::string("isMakerBettingOutcomeOne"),
                      isMakerBettingOutcomeOne},
                 };
                 ccxt::any encoded = this->ethEncodeStructuredData(
                     domain, messageTypes, messageData);
                 ccxt::any digest = this->hashEip712Digest(encoded);
                 ccxt::any orderSignature =
                     this->signDigest(digest, this->privateKey);
                 ccxt::any orderItem = ccxt::dict{
                     {std::string("marketHash"), marketHash},
                     {std::string("maker"), maker},
                     {std::string("totalBetSize"), totalBetSize},
                     {std::string("percentageOdds"), percentageOdds},
                     {std::string("salt"), saltHex},
                     {std::string("expiry"), expiry},
                     {std::string("baseToken"), baseToken},
                     {std::string("isMakerBettingOutcomeOne"),
                      isMakerBettingOutcomeOne},
                     {std::string("timeInForce"), timeInForce},
                     {std::string("orderSignature"), orderSignature},
                 };
                 ccxt::any clientOrderId = this->safeString(
                     paramsTimeInForce, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(orderItem, std::string("clientOrderId"),
                              clientOrderId);
                 }
                 // useBetCredits and externalUserId are per-order fields -
                 // route them into the order item, not the top-level body,
                 // where the venue would silently ignore them
                 ccxt::any useBetCredits = this->safeBool(
                     paramsTimeInForce, std::string("useBetCredits"));
                 if (isTrue(!isEqual(useBetCredits, ccxt::any{}))) {
                   ::setValue(orderItem, std::string("useBetCredits"),
                              useBetCredits);
                 }
                 ccxt::any externalUserId = this->safeString(
                     paramsTimeInForce, std::string("externalUserId"));
                 if (isTrue(!isEqual(externalUserId, ccxt::any{}))) {
                   ::setValue(orderItem, std::string("externalUserId"),
                              externalUserId);
                 }
                 ccxt::any waitForOutcome = this->safeBool(
                     paramsTimeInForce, std::string("waitForOutcome"), true);
                 ccxt::any rest = this->omit(
                     paramsTimeInForce,
                     ccxt::list{std::string("salt"), std::string("expiry"),
                                std::string("clientOrderId"),
                                std::string("waitForOutcome"),
                                std::string("useBetCredits"),
                                std::string("externalUserId")});
                 ccxt::any request = ccxt::dict{
                     {std::string("orders"), ccxt::list{orderItem}},
                     {std::string("waitForOutcome"), waitForOutcome},
                 };
                 ccxt::any response = awaitValue(this->sxbetPrivatePostOrdersV3(
                     this->extend(request, rest)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any results =
                     this->safeList(data, std::string("orders"), ccxt::list{});
                 ccxt::any first = this->safeDict(results, 0, ccxt::dict{});
                 ccxt::any status =
                     this->safeStringUpper(first, std::string("status"));
                 if (isTrue(isEqual(status, std::string("FAILED")))) {
                   ccxt::any reason = this->safeString(
                       first, std::string("reason"), std::string("FAILED"));
                   ccxt::any feedback = add(
                       add(this->id, std::string(" createOrder() rejected: ")),
                       reason);
                   this->throwExactlyMatchedException(
                       ::getValue(this->exceptions, std::string("exact")),
                       reason, feedback);
                   throw InvalidOrder(toString(feedback));
                 }
                 // with waitForOutcome the venue reports the matching result
                 // inline:
                 //     "outcome": { "state": "FULLY_FILLED", "fillAmount":
                 //     "2000000", "remainingAmount": "0", "matchIds": [...] }
                 // documented states: RESTED, FULLY_FILLED, PARTIAL_FILL_DONE,
                 // PARTIAL_FILL_RESTED, TIMEOUT and CANCELLED with cancelReason
                 // NO_LIQUIDITY, INTERNAL_ERROR, ENGINE_SHUTDOWN, EXPIRED or
                 // INSUFFICIENT_BALANCE
                 ccxt::any matchOutcome =
                     this->safeDict(first, std::string("outcome"));
                 ccxt::any usdcDecimals = std::string("1000000");
                 ccxt::any filled = ccxt::any{};
                 ccxt::any remaining = ccxt::any{};
                 ccxt::any orderStatus = ccxt::any{};
                 if (isTrue(!isEqual(matchOutcome, ccxt::any{}))) {
                   ccxt::any fillAmountRaw = this->safeString(
                       matchOutcome, std::string("fillAmount"));
                   ccxt::any remainingRaw = this->safeString(
                       matchOutcome, std::string("remainingAmount"));
                   if (isTrue(!isEqual(fillAmountRaw, ccxt::any{}))) {
                     filled = this->parseNumber(ccxt::Precise::stringDiv(
                         fillAmountRaw, usdcDecimals, 6));
                   }
                   if (isTrue(!isEqual(remainingRaw, ccxt::any{}))) {
                     remaining = this->parseNumber(ccxt::Precise::stringDiv(
                         remainingRaw, usdcDecimals, 6));
                   }
                   ccxt::any state = this->safeStringUpper(
                       matchOutcome, std::string("state"));
                   if (isTrue(
                           isTrue((isEqual(state, std::string("RESTED")))) ||
                           isTrue((isEqual(
                               state, std::string("PARTIAL_FILL_RESTED")))))) {
                     orderStatus = std::string("open");
                   } else if (isTrue(isEqual(state,
                                             std::string("FULLY_FILLED")))) {
                     orderStatus = std::string("closed");
                   } else if (isTrue(isEqual(
                                  state, std::string("PARTIAL_FILL_DONE")))) {
                     // the unmatched remainder of an IOC was cancelled by the
                     // venue
                     orderStatus = std::string("canceled");
                   } else if (isTrue(
                                  isEqual(state, std::string("CANCELLED")))) {
                     // the documented field is cancelReason; 'reason' is kept
                     // for older responses
                     ccxt::any reason = this->safeStringUpper2(
                         matchOutcome, std::string("cancelReason"),
                         std::string("reason"));
                     orderStatus =
                         (isTrue((isEqual(reason, std::string("EXPIRED"))))
                              ? ccxt::any(std::string("expired"))
                              : ccxt::any(std::string("canceled")));
                   }
                 }
                 ccxt::any now = this->milliseconds();
                 return this->safePredictionOrder(
                     ccxt::dict{
                         {std::string("id"),
                          this->safeString2(first, std::string("orderId"),
                                            std::string("orderHash"))},
                         {std::string("clientOrderId"),
                          this->safeString(first, std::string("clientOrderId"),
                                           clientOrderId)},
                         {std::string("info"), response},
                         {std::string("timestamp"), now},
                         {std::string("datetime"), this->iso8601(now)},
                         {std::string("status"), orderStatus},
                         {std::string("filled"), filled},
                         {std::string("remaining"), remaining},
                         {std::string("cost"), filled},
                         {std::string("outcome"),
                          this->safeString(outcomeObj, std::string("outcome"))},
                         {std::string("outcomeId"), outcomeId},
                         {std::string("label"),
                          this->safeString(outcomeObj, std::string("label"))},
                         {std::string("market"),
                          this->safeString(outcomeObj, std::string("market"))},
                         {std::string("type"), type},
                         {std::string("timeInForce"), timeInForce},
                         {std::string("side"), side},
                         {std::string("price"),
                          this->parseNumber(roundedProbability)},
                         {std::string("amount"), amount},
                         {std::string("fee"), ccxt::any{}},
                         {std::string("trades"), ccxt::list{}},
                     },
                     outcomeObj);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetCancelResponse
   * @description parses the shared v3 cancel response ({cancelled,
   * notCancelled, unconfirmed}) into order structures
   * @param {object} response the raw DELETE /orders-v3 response
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  virtual ccxt::any parseSxbetCancelResponse(ccxt::any response) {
    ccxt::any data =
        this->safeDict(response, std::string("data"), ccxt::dict{});
    ccxt::any result = ccxt::list{};
    // by-id cancels report 'cancelled'; the /all and /event paths submit
    // asynchronously and report 'cancelledSubmitted' instead - treat both like
    // cancelled
    ccxt::any cancelled =
        this->safeList2(data, std::string("cancelled"),
                        std::string("cancelledSubmitted"), ccxt::list{});
    ccxt::any cancelledLength = getArrayLength(cancelled);
    for (ccxt::any i = 0; isLessThan(i, cancelledLength); postFixIncrement(i)) {
      arrayPush(result, this->safePredictionOrder(ccxt::dict{
                            {std::string("id"),
                             this->safeString(::getValue(cancelled, i),
                                              std::string("orderId"))},
                            {std::string("status"), std::string("canceled")},
                            {std::string("info"), response},
                        }));
    }
    ccxt::any notCancelled =
        this->safeList(data, std::string("notCancelled"), ccxt::list{});
    ccxt::any notCancelledLength = getArrayLength(notCancelled);
    for (ccxt::any i = 0; isLessThan(i, notCancelledLength);
         postFixIncrement(i)) {
      // the venue reports why (e.g. NOT_FOUND) - the order was not cancelled,
      // report it honestly
      arrayPush(result, this->safePredictionOrder(ccxt::dict{
                            {std::string("id"),
                             this->safeString(::getValue(notCancelled, i),
                                              std::string("orderId"))},
                            {std::string("status"), ccxt::any{}},
                            {std::string("info"), response},
                        }));
    }
    ccxt::any unconfirmed =
        this->safeList(data, std::string("unconfirmed"), ccxt::list{});
    ccxt::any unconfirmedLength = getArrayLength(unconfirmed);
    for (ccxt::any i = 0; isLessThan(i, unconfirmedLength);
         postFixIncrement(i)) {
      arrayPush(result, this->safePredictionOrder(ccxt::dict{
                            {std::string("id"),
                             this->safeString(::getValue(unconfirmed, i),
                                              std::string("orderId"))},
                            {std::string("status"), ccxt::any{}},
                            {std::string("info"), response},
                        }));
    }
    return result;
  }

  /**
   * @method
   * @name sxbet#cancelOrder
   * @description cancels one resting maker order - v3 cancels are plain
   * api-key-authenticated DELETE requests, no signature involved
   * @see https://docs.sx.bet/api-reference/delete-orders-v3
   * @param {string} id the order id
   * @param {string} [outcome] not used by sxbet.cancelOrder
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction order
   * structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any outcome = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 ccxt::any request = ccxt::dict{
                     {std::string("orders"), ccxt::list{ccxt::dict{
                                                 {std::string("orderId"), id},
                                             }}},
                 };
                 ccxt::any response =
                     awaitValue(this->sxbetPrivateDeleteOrdersV3(
                         this->extend(request, params)));
                 ccxt::any orders = this->parseSxbetCancelResponse(response);
                 ccxt::any first = this->safeDict(orders, 0);
                 return first;
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#cancelOrders
   * @description cancels multiple resting maker orders in one request - v3
   * cancels are plain api-key-authenticated DELETE requests, no signature
   * involved
   * @see https://docs.sx.bet/api-reference/delete-orders-v3
   * @param {string[]} ids the order ids to cancel
   * @param {string} [outcome] not used by sxbet.cancelOrders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  cancelOrders(ccxt::any ids, ccxt::any outcome = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 ccxt::any idsLength = getArrayLength(ids);
                 if (isTrue(isEqual(idsLength, 0))) {
                   throw ArgumentsRequired(toString(
                       add(this->id, std::string(" cancelOrders() requires a "
                                                 "non-empty ids argument"))));
                 }
                 // the venue caps one cancel request at maxCancelOrders ids
                 // (100, see /metadata/obv3) - chunk larger batches instead of
                 // letting the whole request 400
                 ccxt::any chunkSize = this->safeInteger(
                     this->options, std::string("cancelOrdersBatchSize"), 100);
                 ccxt::any chunkCount = this->parseToInt(divide(
                     this->sum(idsLength, subtract(chunkSize, 1)), chunkSize));
                 ccxt::any result = ccxt::list{};
                 for (ccxt::any c = 0; isLessThan(c, chunkCount);
                      postFixIncrement(c)) {
                   ccxt::any start = multiply(c, chunkSize);
                   ccxt::any end = add(start, chunkSize);
                   if (isTrue(isGreaterThan(end, idsLength))) {
                     end = idsLength;
                   }
                   ccxt::any orderItems = ccxt::list{};
                   for (ccxt::any i = start; isLessThan(i, end);
                        postFixIncrement(i)) {
                     arrayPush(orderItems,
                               ccxt::dict{
                                   {std::string("orderId"), ::getValue(ids, i)},
                               });
                   }
                   ccxt::any request = ccxt::dict{
                       {std::string("orders"), orderItems},
                   };
                   ccxt::any response =
                       awaitValue(this->sxbetPrivateDeleteOrdersV3(
                           this->extend(request, params)));
                   result = this->arrayConcat(
                       result, this->parseSxbetCancelResponse(response));
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#cancelAllOrders
   * @description cancels every resting maker order of the account, or every
   * order of one fixture via params.eventId - v3 cancels are plain
   * api-key-authenticated DELETE requests, no signature involved
   * @see https://docs.sx.bet/api-reference/delete-orders-v3-all
   * @see https://docs.sx.bet/api-reference/delete-orders-v3-event
   * @param {string} [outcome] not used by sxbet.cancelAllOrders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.eventId] cancels every order across every market of
   * this fixture instead of the account-wide path (params.sportXeventId is
   * accepted too)
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  virtual std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any outcome = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 ccxt::any eventId =
                     this->safeString2(params, std::string("eventId"),
                                       std::string("sportXeventId"));
                 ccxt::any rest = this->omit(
                     params, ccxt::list{std::string("eventId"),
                                        std::string("sportXeventId")});
                 ccxt::any isEventScoped = (!isEqual(eventId, ccxt::any{}));
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEventScoped)) {
                   // the event route takes eventId in the QUERY string, not the
                   // body - sign() urlencodes body-less DELETE params
                   ccxt::any request = ccxt::dict{
                       {std::string("eventId"), eventId},
                   };
                   response = awaitValue(this->sxbetPrivateDeleteOrdersV3Event(
                       this->extend(request, rest)));
                 } else {
                   response =
                       awaitValue(this->sxbetPrivateDeleteOrdersV3All(rest));
                 }
                 ccxt::any result = this->parseSxbetCancelResponse(response);
                 // both paths paginate their async submission - keep going on
                 // the SAME route while more remain
                 ccxt::any hasMore = this->safeBool(
                     this->safeDict(response, std::string("data"),
                                    ccxt::dict{}),
                     std::string("hasMore"), false);
                 ccxt::any guard = 0;
                 while (isTrue((isEqual(hasMore, true))) &&
                        isTrue((isLessThan(guard, 50)))) {
                   ccxt::any nextResponse = ccxt::any{};
                   if (isTrue(isEventScoped)) {
                     ccxt::any nextRequest = ccxt::dict{
                         {std::string("eventId"), eventId},
                     };
                     nextResponse =
                         awaitValue(this->sxbetPrivateDeleteOrdersV3Event(
                             this->extend(nextRequest, rest)));
                   } else {
                     nextResponse =
                         awaitValue(this->sxbetPrivateDeleteOrdersV3All(rest));
                   }
                   result = this->arrayConcat(
                       result, this->parseSxbetCancelResponse(nextResponse));
                   hasMore = this->safeBool(this->safeDict(nextResponse,
                                                           std::string("data"),
                                                           ccxt::dict{}),
                                            std::string("hasMore"), false);
                   guard = this->sum(guard, 1);
                 }
                 return result;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parsePredictionOrder
   * @description parses one raw GET /orders row into a unified prediction
   * order. every sx.bet maker order is a 'buy' of the outcome it bets on
   * (isMakerBettingOutcomeOne selects the side), priced at the maker's own
   * implied probability
   * @param {object} order the raw sx.bet order object
   * @param {object} [market] the outcome object the order belongs to (resolved
   * from the cache by outcomeId when omitted)
   * @returns {object} a [prediction order
   * structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  ccxt::any parsePredictionOrder(ccxt::any order,
                                 ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "id":
    //         "0x112a4f19f20395aefcdb5d26f3f8aab0d96b1aff7ce346c0bfb13d9490340cdf",
    //         "marketHash":
    //         "0xbf06c6379c922d8118612d1d7493b20f6df6929437fbf6022904327f9516a2eb",
    //         "userAddress": "0xbcc6D643e4159A75ED1dB4e13330230B82F2AEe5",
    //         "wallet": "0x4361123dbdc1D812fdf7D27045aF358C9C8AA70A",
    //         "isBettingOutcomeOne": true,
    //         "percentageOdds": "40000000000000000000",
    //         "totalBetSize": "3000000",
    //         "remainingSize": "3000000",
    //         "expiry": null,
    //         "status": "ACTIVE",
    //         "inactiveReason": null,
    //         "eventId": "L12003787",
    //         "createdAt": "2026-07-31T18:45:42.636Z",
    //         "updatedAt": "2026-07-31T18:45:42.838Z"
    //     }
    //
    ccxt::any orderId =
        this->safeString2(order, std::string("id"), std::string("orderId"));
    ccxt::any marketHash =
        this->safeString(order, std::string("marketHash"), std::string(""));
    ccxt::any isBettingOutcomeOne =
        this->safeBool(order, std::string("isBettingOutcomeOne"), true);
    ccxt::any outcomeId = ccxt::any{};
    if (isTrue(isBettingOutcomeOne)) {
      outcomeId = marketHash;
    } else {
      outcomeId = (add(marketHash, std::string("-2")));
    }
    ccxt::any outcomeObj = this->safeOutcome(outcomeId, market);
    ccxt::any oneDenom = std::string("100000000000000000000");
    ccxt::any usdcDecimals = std::string("1000000");
    ccxt::any percentageOdds =
        this->safeString(order, std::string("percentageOdds"));
    ccxt::any price =
        (isTrue((!isEqual(percentageOdds, ccxt::any{})))
             ? ccxt::any(this->parseNumber(
                   ccxt::Precise::stringDiv(percentageOdds, oneDenom)))
             : ccxt::any(ccxt::any{}));
    ccxt::any totalBetSize =
        this->safeString(order, std::string("totalBetSize"), std::string("0"));
    ccxt::any remainingSize =
        this->safeString(order, std::string("remainingSize"), totalBetSize);
    ccxt::any filledRaw = ccxt::Precise::stringSub(totalBetSize, remainingSize);
    ccxt::any amount = this->parseNumber(
        ccxt::Precise::stringDiv(totalBetSize, usdcDecimals, 6));
    ccxt::any filled =
        this->parseNumber(ccxt::Precise::stringDiv(filledRaw, usdcDecimals, 6));
    ccxt::any remaining = this->parseNumber(
        ccxt::Precise::stringDiv(remainingSize, usdcDecimals, 6));
    ccxt::any orderStatus = this->safeStringUpper(order, std::string("status"));
    ccxt::any inactiveReason =
        this->safeStringUpper(order, std::string("inactiveReason"));
    ccxt::any status = std::string("open");
    if (isTrue(isEqual(orderStatus, std::string("INACTIVE")))) {
      // documented inactiveReason enum: FILLED, USER_REQUESTED, EXPIRED,
      // NO_LIQUIDITY, INSUFFICIENT_BALANCE, EVENT_LIFECYCLE, MARKET_HALTED,
      // HEARTBEAT_TIMEOUT, SYSTEM
      if (isTrue(isEqual(inactiveReason, std::string("FILLED")))) {
        status = std::string("closed");
      } else if (isTrue(isEqual(inactiveReason, std::string("EXPIRED")))) {
        status = std::string("expired");
      } else {
        status = std::string("canceled");
      }
    }
    ccxt::any timestamp =
        this->parse8601(this->safeString(order, std::string("createdAt")));
    return this->safePredictionOrder(
        ccxt::dict{
            {std::string("id"), orderId},
            {std::string("clientOrderId"),
             this->safeString(order, std::string("clientOrderId"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"),
             this->parse8601(
                 this->safeString(order, std::string("updatedAt")))},
            {std::string("status"), status},
            {std::string("type"), std::string("limit")},
            {std::string("timeInForce"), ccxt::any{}},
            {std::string("side"), std::string("buy")},
            {std::string("price"), price},
            {std::string("average"), ccxt::any{}},
            {std::string("amount"), amount},
            {std::string("filled"), filled},
            {std::string("remaining"), remaining},
            {std::string("cost"), ccxt::any{}},
            {std::string("fee"), ccxt::any{}},
            {std::string("reduceOnly"), ccxt::any{}},
            {std::string("postOnly"), ccxt::any{}},
            {std::string("trades"), ccxt::list{}},
            {std::string("outcome"),
             this->safeString(outcomeObj, std::string("outcome"))},
            {std::string("outcomeId"),
             this->safeString(outcomeObj, std::string("outcomeId"), outcomeId)},
            {std::string("label"),
             this->safeString(outcomeObj, std::string("label"))},
            {std::string("market"),
             this->safeString(outcomeObj, std::string("market"))},
            {std::string("info"), order},
        },
        outcomeObj);
  }

  /**
   * @ignore
   * @method
   * @name sxbet#clampSxbetPerPage
   * @description clamps a user limit to the venue's hard perPage ceiling -
   * every v3 listing route rejects perPage above 100, and deeper history is
   * reachable through the nextKey cursor instead
   * @param {int} limit the user-requested limit
   * @returns {int} the limit clamped to at most 100
   */
  virtual ccxt::any clampSxbetPerPage(ccxt::any limit) {
    ccxt::any maxPerPage = 100;
    if (isTrue(isEqual(limit, ccxt::any{}))) {
      return ccxt::any{};
    }
    return (isTrue((isGreaterThan(limit, maxPerPage))) ? ccxt::any(maxPerPage)
                                                       : ccxt::any(limit));
  }

  /**
   * @method
   * @name sxbet#fetchOpenOrders
   * @description fetches the account's resting maker orders via the
   * api-key-authenticated GET /orders-v3 (the route is hardcoded to ACTIVE
   * orders and scoped to the key's account)
   * @see https://docs.sx.bet/api-reference/get-orders-v3
   * @param {string} [outcome] unified outcome or outcomeId — narrows to that
   * outcome's market
   * @param {int} [since] applied client-side (the route has no date filter;
   * rows carry createdAt)
   * @param {int} [limit] the maximum number of orders to return (server-side
   * perPage, max 100, default 50)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint (e.g. eventId, sortBy, sortAsc, nextKey)
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any outcome = ccxt::any{},
                  ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any request = ccxt::dict{};
                 ccxt::any outcomeObj = ccxt::any{};
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   outcomeObj = this->outcome(outcome);
                   ::setValue(request, std::string("marketHash"),
                              this->safeString(
                                  ::getValue(outcomeObj, std::string("info")),
                                  std::string("marketHash")));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("perPage"),
                              this->clampSxbetPerPage(limit));
                 }
                 ccxt::any response = awaitValue(this->sxbetPrivateGetOrdersV3(
                     this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rawOrders =
                     this->safeList(data, std::string("orders"), ccxt::list{});
                 return this->parsePredictionOrders(rawOrders, outcomeObj,
                                                    since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchOrders
   * @description fetches the account's maker orders. sx.bet's GET /orders-v3
   * listing is hardcoded to ACTIVE orders — filled/cancelled/expired orders
   * leave the listing permanently (their history is only reconstructable from
   * fills), so this returns the same set that fetchOpenOrders returns
   * @see https://docs.sx.bet/api-reference/get-orders-v3
   * @param {string} [outcome] unified outcome or outcomeId — narrows to that
   * outcome's market
   * @param {int} [since] applied client-side (the route has no date filter;
   * rows carry createdAt)
   * @param {int} [limit] the maximum number of orders to return (server-side
   * perPage, max 100, default 50)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint (e.g. eventId, sortBy, sortAsc, nextKey)
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any outcome = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        return awaitValue(this->fetchOpenOrders(outcome, since,
                                                                limit, params));
                      })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchOrder
   * @description fetches a single maker order by its order hash - unlike the
   * listing, GET /orders-v3/{orderId} also serves filled, cancelled and expired
   * orders while they still exist. a missing or foreign id 404s with 'Order not
   * found', surfaced through handleErrors's OrderNotFound mapping
   * @see https://docs.sx.bet/api-reference/get-order-v3
   * @param {string} id the order hash
   * @param {string} [outcome] unified outcome or outcomeId (labelling hint
   * only, the request needs just the id)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction order
   * structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  virtual std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any outcome = ccxt::any{},
             ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 if (isTrue(isEqual(id, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(" fetchOrder() requires an id argument"))));
                 }
                 ccxt::any outcomeObj = ccxt::any{};
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   outcomeObj = this->outcome(outcome);
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("orderId"), id},
                 };
                 ccxt::any response =
                     awaitValue(this->sxbetPrivateGetOrdersV3OrderId(
                         this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any row =
                     this->safeDict(data, std::string("order"), data);
                 return this->parsePredictionOrder(row, outcomeObj);
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchTrades
   * @description fetches the public trade tape of one outcome's market — every
   * bettor's settled and in-flight bets on that market. the venue requires the
   * trades listing to be scoped, so the outcome argument is mandatory
   * @see https://docs.sx.bet/api-reference/get-trades-v3-public
   * @param {string} outcome unified outcome or outcomeId
   * @param {int} [since] timestamp in ms of the earliest trade to return —
   * applied client-side over the newest page (the public tape serves
   * newest-first and has no date filter; older pages are reachable through
   * params.nextKey)
   * @param {int} [limit] the maximum number of trades to return (server-side
   * perPage, max 100, default 50)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint (e.g. eventId, nextKey)
   * @returns {object[]} a list of [prediction trade
   * structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any outcome, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(outcome, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchTrades() requires an outcome argument - the "
                           "venue requires the trades listing to be scoped"))));
                 }
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any request = ccxt::dict{
                     {std::string("marketHash"),
                      this->safeString(
                          ::getValue(outcomeObj, std::string("info")),
                          std::string("marketHash"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("perPage"),
                              this->clampSxbetPerPage(limit));
                 }
                 ccxt::any response =
                     awaitValue(this->sxbetPublicGetTradesV3Public(
                         this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rawTrades =
                     this->safeList(data, std::string("trades"), ccxt::list{});
                 ccxt::any trades = ccxt::list{};
                 ccxt::any rawTradesLength = getArrayLength(rawTrades);
                 for (ccxt::any i = 0; isLessThan(i, rawTradesLength);
                      postFixIncrement(i)) {
                   arrayPush(trades, this->parseSxbetV3PublicTrade(
                                         ::getValue(rawTrades, i)));
                 }
                 // the venue serves the tape newest-first - the unified
                 // contract is ascending by timestamp
                 trades = this->sortBy(trades, std::string("timestamp"));
                 ccxt::any sym =
                     this->safeString(outcomeObj, std::string("outcome"));
                 return this->filterByValueSinceLimit(
                     trades, std::string("outcome"), sym, since, limit,
                     std::string("timestamp"), true);
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchMyTrades
   * @description fetches the account's fills (matched legs of its own orders,
   * both taker and maker side) via the api-key-authenticated GET /fills-v3
   * @see https://docs.sx.bet/api-reference/get-fills-v3
   * @param {string} [outcome] unified outcome or outcomeId — narrows to that
   * outcome's market and drops the opposite side's legs
   * @param {int} [since] timestamp in ms of the earliest fill to fetch
   * (server-side startDate)
   * @param {int} [limit] the maximum number of fills to return (server-side
   * perPage, max 100, default 50)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint (e.g. tradeId, orderId, endDate, sortAsc, nextKey)
   * @returns {object[]} a list of [prediction trade
   * structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any outcome = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 ccxt::any request = ccxt::dict{};
                 ccxt::any outcomeObj = ccxt::any{};
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   outcomeObj = this->outcome(outcome);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startDate"),
                              this->iso8601(since));
                 }
                 if (isTrue(isTrue((!isEqual(limit, ccxt::any{}))) &&
                            isTrue((isEqual(outcome, ccxt::any{}))))) {
                   // with an outcome filter the rows are narrowed client-side -
                   // a server-side page size would truncate the page before the
                   // filter and under-fill the result
                   ::setValue(request, std::string("perPage"),
                              this->clampSxbetPerPage(limit));
                 }
                 ccxt::any response = awaitValue(this->sxbetPrivateGetFillsV3(
                     this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rawFills =
                     this->safeList(data, std::string("fills"), ccxt::list{});
                 ccxt::any trades = ccxt::list{};
                 ccxt::any rawFillsLength = getArrayLength(rawFills);
                 for (ccxt::any i = 0; isLessThan(i, rawFillsLength);
                      postFixIncrement(i)) {
                   arrayPush(trades,
                             this->parseSxbetV3Fill(::getValue(rawFills, i)));
                 }
                 trades = this->sortBy(trades, std::string("timestamp"));
                 ccxt::any sym = (isTrue((!isEqual(outcomeObj, ccxt::any{})))
                                      ? ccxt::any(this->safeString(
                                            outcomeObj, std::string("outcome")))
                                      : ccxt::any(ccxt::any{}));
                 return this->filterByValueSinceLimit(
                     trades, std::string("outcome"), sym, since, limit,
                     std::string("timestamp"), true);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetV3Fill
   * @description parses one GET /fills-v3 row into a unified trade - each fill
   * is one maker/taker match of the wallet's own order
   * @param {object} fill the raw fill row
   * @param {object} [market] the outcome object labelling hint
   * @returns {object} a [prediction trade
   * structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  virtual ccxt::any parseSxbetV3Fill(ccxt::any fill,
                                     ccxt::any market = ccxt::any{}) {
    //
    //     {
    //         "id": "0xec8e...:0x02d2...:0x1fec...",
    //         "matchId": "0xec8e...", "orderId": "0x02d2...", "tradeId":
    //         "0xac6b...", "marketHash": "0x1fec...", "isParlay": false,
    //         "userAddress": "0xbcc6...", "wallet": "0x4361...",
    //         "fillAmount": "333334", "fillOdds": "40000000000000000000",
    //         "returnAmount": "833335", "isBettingOutcomeOne": false,
    //         "isMaker": false, "status": "LOCKED", "txHash": "0x6430...",
    //         "ceRefundAmount": "0", "ceRefundFeeAmount": "0",
    //         "usedBetCredits": false, "createdAt": "2026-07-31T18:47:09.586Z",
    //         "updatedAt": "2026-07-31T18:47:12.837Z", "settlement": null
    //     }
    //
    ccxt::any marketHash =
        this->safeString(fill, std::string("marketHash"), std::string(""));
    ccxt::any isBettingOutcomeOne =
        this->safeBool(fill, std::string("isBettingOutcomeOne"), true);
    ccxt::any outcomeId = ccxt::any{};
    if (isTrue(isBettingOutcomeOne)) {
      outcomeId = marketHash;
    } else {
      outcomeId = (add(marketHash, std::string("-2")));
    }
    ccxt::any outcomeObj = this->safeOutcome(outcomeId, market);
    ccxt::any oneDenom = std::string("100000000000000000000");
    ccxt::any usdcDecimals = std::string("1000000");
    ccxt::any fillOdds = this->safeString(fill, std::string("fillOdds"));
    ccxt::any price = (isTrue((!isEqual(fillOdds, ccxt::any{})))
                           ? ccxt::any(this->parseNumber(
                                 ccxt::Precise::stringDiv(fillOdds, oneDenom)))
                           : ccxt::any(ccxt::any{}));
    ccxt::any fillAmount =
        this->safeString(fill, std::string("fillAmount"), std::string("0"));
    ccxt::any amount = this->parseNumber(
        ccxt::Precise::stringDiv(fillAmount, usdcDecimals, 6));
    ccxt::any timestamp =
        this->parse8601(this->safeString(fill, std::string("createdAt")));
    // isMaker: true when the account's order was the resting one - absent on
    // older rows
    ccxt::any isMaker = this->safeBool(fill, std::string("isMaker"));
    ccxt::any takerOrMaker = ccxt::any{};
    if (isTrue(!isEqual(isMaker, ccxt::any{}))) {
      takerOrMaker =
          (isTrue((isEqual(isMaker, true))) ? ccxt::any(std::string("maker"))
                                            : ccxt::any(std::string("taker")));
    }
    return this->safePredictionTrade(
        ccxt::dict{
            {std::string("id"), this->safeString(fill, std::string("id"))},
            {std::string("info"), fill},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("outcome"),
             this->safeString(outcomeObj, std::string("outcome"))},
            {std::string("outcomeId"),
             this->safeString(outcomeObj, std::string("outcomeId"), outcomeId)},
            {std::string("label"),
             this->safeString(outcomeObj, std::string("label"))},
            {std::string("market"),
             this->safeString(outcomeObj, std::string("market"))},
            {std::string("order"),
             this->safeString(fill, std::string("orderId"))},
            {std::string("type"), ccxt::any{}},
            {std::string("side"), std::string("buy")},
            {std::string("takerOrMaker"), takerOrMaker},
            {std::string("price"), price},
            {std::string("amount"), amount},
            {std::string("cost"), amount},
            {std::string("fee"), ccxt::any{}},
        },
        market);
  }

  /**
   * @method
   * @name sxbet#fetchBalance
   * @description fetches the account's order-spendable proxy balance from GET
   * /user/balance-v3 - v3 trading capital sits inside the obv3 proxy wallet
   * (funded via approve()), and GTC posting is checked against availableAmount.
   * free is the spendable availableAmount, used the escrowedAmount locked
   * behind open bets
   * @see https://docs.sx.bet/api-reference/get-user-balance-v3
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance
   * structure](https://docs.ccxt.com/#/?id=balance-structure)
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any obv3 = awaitValue(this->loadSxObv3Metadata());
                 ccxt::any activeAsset = this->safeDict(
                     obv3, std::string("activeAsset"), ccxt::dict{});
                 ccxt::any usdcAddress = this->safeStringLower(
                     activeAsset, std::string("baseToken"), std::string(""));
                 ccxt::any response =
                     awaitValue(this->sxbetPrivateGetUserBalanceV3(params));
                 //
                 //     { "status": "success", "data": { "balances": [ {
                 //         "userAddress": "0xC3f4...", "wallet": "0x19D1...",
                 //         "tokenAddress": "0x1BC6...", "escrowAddress":
                 //         "0x0Db3...", "availableAmount": "0",
                 //         "pendingAvailableAmount": "0", "escrowedAmount":
                 //         "0", "pendingEscrowAmount": "0" } ] } }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any balances = this->safeList(
                     data, std::string("balances"), ccxt::list{});
                 ccxt::any result = ccxt::dict{
                     {std::string("info"), response},
                 };
                 ccxt::any usdcDecimals = std::string("1000000");
                 ccxt::any balancesLength = getArrayLength(balances);
                 for (ccxt::any i = 0; isLessThan(i, balancesLength);
                      postFixIncrement(i)) {
                   ccxt::any row = this->safeDict(balances, i);
                   ccxt::any tokenAddress = this->safeStringLower(
                       row, std::string("tokenAddress"), std::string(""));
                   // every sxbet market is denominated in the active base
                   // token, surfaced under 'USDC'; rows of any other token keep
                   // their contract address for the code
                   ccxt::any code = this->safeString(
                       row, std::string("tokenAddress"), std::string(""));
                   if (isTrue(isEqual(tokenAddress, usdcAddress))) {
                     code = std::string("USDC");
                   }
                   ccxt::any free = ccxt::Precise::stringDiv(
                       this->safeString(row, std::string("availableAmount"),
                                        std::string("0")),
                       usdcDecimals, 6);
                   ccxt::any used = ccxt::Precise::stringDiv(
                       this->safeString(row, std::string("escrowedAmount"),
                                        std::string("0")),
                       usdcDecimals, 6);
                   ::setValue(
                       result, code,
                       ccxt::dict{
                           {std::string("free"), this->parseNumber(free)},
                           {std::string("used"), this->parseNumber(used)},
                           {std::string("total"),
                            this->parseNumber(
                                ccxt::Precise::stringAdd(free, used))},
                       });
                 }
                 return this->safeBalance(result);
               })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchPositions
   * @description fetches the account's open positions from the venue's
   * per-market aggregates (GET /positions-v3, MATCHED and LOCKED bets by
   * default; override with params.status - the enum is MATCHED, LOCKED,
   * SETTLED, FAILED, and pnl is populated only when the filter is exclusively
   * SETTLED). contracts is the total stake at risk, entryPrice the blended
   * implied probability of the market's best-case outcome
   * @see https://docs.sx.bet/api-reference/get-positions-v3
   * @param {string[]} [outcomes] filter by unified outcomes or outcomeIds
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction position
   * structures](https://docs.ccxt.com/#/?id=prediction-position-structure)
   */
  std::shared_future<ccxt::any>
  fetchPositions(ccxt::any outcomes = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 // copy to a plain list so the transpilers and the strict null
                 // checks see one shape
                 ccxt::any outcomesList =
                     (isTrue((isEqual(outcomes, ccxt::any{})))
                          ? ccxt::any(ccxt::list{})
                          : ccxt::any(outcomes));
                 ccxt::any outcomesLength = getArrayLength(outcomesList);
                 ccxt::any wantedMarkets = ccxt::dict{};
                 if (isTrue(isGreaterThan(outcomesLength, 0))) {
                   awaitValue(this->loadOutcomes(outcomesList));
                   for (ccxt::any i = 0; isLessThan(i, outcomesLength);
                        postFixIncrement(i)) {
                     ccxt::any outcomeObj =
                         this->outcome(::getValue(outcomesList, i));
                     ccxt::any hash = this->safeString(
                         ::getValue(outcomeObj, std::string("info")),
                         std::string("marketHash"), std::string(""));
                     ::setValue(wantedMarkets, hash, true);
                   }
                 }
                 // open exposure lives in MATCHED and LOCKED bets - the venue
                 // requires an explicit status list drawn from MATCHED, LOCKED,
                 // SETTLED, FAILED
                 ccxt::any request = ccxt::dict{
                     {std::string("status"),
                      this->safeString(params, std::string("status"),
                                       std::string("MATCHED,LOCKED"))},
                 };
                 ccxt::any rest =
                     this->omit(params, ccxt::list{std::string("status")});
                 ccxt::any response =
                     awaitValue(this->sxbetPrivateGetPositionsV3(
                         this->extend(request, rest)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rawPositions = this->safeList(
                     data, std::string("positions"), ccxt::list{});
                 ccxt::any result = ccxt::list{};
                 ccxt::any rawPositionsLength = getArrayLength(rawPositions);
                 for (ccxt::any i = 0; isLessThan(i, rawPositionsLength);
                      postFixIncrement(i)) {
                   ccxt::any raw = ::getValue(rawPositions, i);
                   ccxt::any marketHash = this->safeString(
                       raw, std::string("marketHash"), std::string(""));
                   if (isTrue(isGreaterThan(outcomesLength, 0))) {
                     if (isTrue(
                             isEqual(this->safeBool(wantedMarkets, marketHash),
                                     ccxt::any{}))) {
                       continue;
                     }
                   }
                   arrayPush(result, this->parseSxbetV3Position(raw));
                 }
                 return result;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetV3Position
   * @description parses one GET /positions-v3 row (per-market aggregate) into a
   * unified position on the market's best-case outcome
   * @param {object} raw the raw position row
   * @returns {object} a [prediction position
   * structure](https://docs.ccxt.com/#/?id=prediction-position-structure)
   */
  virtual ccxt::any parseSxbetV3Position(ccxt::any raw) {
    //
    //     {
    //         "marketHash": "0x8120...", "market": {...},
    //         "totalStake": "300000000", "maxWin": "200000000", "maxLoss":
    //         "-100000000", "isOutcomeOneMaxWin": true, "odds": {"outcomeOne":
    //         "40000000000000000000", "outcomeTwo": "50000000000000000000"},
    //         "pnl": null, "tradeCount": 2,
    //         "betTime": "2026-03-13T21:14:02.118Z", "updatedAt":
    //         "2026-03-13T22:03:41.502Z"
    //     }
    //
    ccxt::any marketHash =
        this->safeString(raw, std::string("marketHash"), std::string(""));
    ccxt::any isOutcomeOneMaxWin =
        this->safeBool(raw, std::string("isOutcomeOneMaxWin"), true);
    ccxt::any outcomeId = ccxt::any{};
    if (isTrue(isOutcomeOneMaxWin)) {
      outcomeId = marketHash;
    } else {
      outcomeId = (add(marketHash, std::string("-2")));
    }
    ccxt::any outcomeObj = this->safeOutcome(outcomeId);
    ccxt::any oneDenom = std::string("100000000000000000000");
    ccxt::any usdcDecimals = std::string("1000000");
    ccxt::any odds = this->safeDict(raw, std::string("odds"), ccxt::dict{});
    ccxt::any ownOdds = ccxt::any{};
    if (isTrue(isOutcomeOneMaxWin)) {
      ownOdds = this->safeString(odds, std::string("outcomeOne"));
    } else {
      ownOdds = this->safeString(odds, std::string("outcomeTwo"));
    }
    ccxt::any entryPrice =
        (isTrue((!isEqual(ownOdds, ccxt::any{})))
             ? ccxt::any(this->parseNumber(
                   ccxt::Precise::stringDiv(ownOdds, oneDenom)))
             : ccxt::any(ccxt::any{}));
    ccxt::any totalStake =
        this->safeString(raw, std::string("totalStake"), std::string("0"));
    ccxt::any pnl = this->safeString(raw, std::string("pnl"));
    ccxt::any timestamp =
        this->parse8601(this->safeString(raw, std::string("betTime")));
    return this->safePredictionPosition(ccxt::dict{
        {std::string("outcome"),
         this->safeString(outcomeObj, std::string("outcome"))},
        {std::string("outcomeId"),
         this->safeString(outcomeObj, std::string("outcomeId"), outcomeId)},
        {std::string("label"),
         this->safeString(outcomeObj, std::string("label"))},
        {std::string("market"),
         this->safeString(outcomeObj, std::string("market"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("lastUpdateTimestamp"),
         this->parse8601(this->safeString(raw, std::string("updatedAt")))},
        {std::string("contracts"), this->parseNumber(ccxt::Precise::stringDiv(
                                       totalStake, usdcDecimals, 6))},
        {std::string("entryPrice"), entryPrice},
        {std::string("markPrice"), ccxt::any{}},
        {std::string("unrealizedPnl"), ccxt::any{}},
        {std::string("realizedPnl"),
         (isTrue((!isEqual(pnl, ccxt::any{})))
              ? ccxt::any(this->parseNumber(
                    ccxt::Precise::stringDiv(pnl, usdcDecimals, 6)))
              : ccxt::any(ccxt::any{}))},
        {std::string("side"), std::string("long")},
        {std::string("info"), raw},
    });
  }

  /**
   * @method
   * @name sxbet#fetchSettlements
   * @description fetches the account's settled bets — each settled GET
   * /trades-v3 row becomes one settlement with the resolved winner, the payout
   * (stake / odds when won, the stake back when the market voided, zero when
   * lost) and the realized pnl
   * @see https://docs.sx.bet/api-reference/get-trades-v3
   * @param {string} [outcome] filter to a single unified outcome or outcomeId
   * @param {int} [since] timestamp in ms of the earliest settlement to fetch
   * (server-side startDate on the bet time)
   * @param {int} [limit] the maximum number of settlements to fetch
   * (server-side perPage, max 100, default 50)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint (e.g. eventId, endDate, sortAsc, nextKey)
   * @returns {object[]} a list of prediction settlement structures
   */
  std::shared_future<ccxt::any>
  fetchSettlements(ccxt::any outcome = ccxt::any{},
                   ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 this->checkRequiredCredentials();
                 ccxt::any request = ccxt::dict{
                     {std::string("status"), std::string("SETTLED")},
                 };
                 ccxt::any wantedOutcomeId = ccxt::any{};
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   ccxt::any outcomeObj = this->outcome(outcome);
                   ::setValue(request, std::string("marketHash"),
                              this->safeString(
                                  ::getValue(outcomeObj, std::string("info")),
                                  std::string("marketHash"), std::string("")));
                   wantedOutcomeId =
                       this->safeString(outcomeObj, std::string("outcomeId"));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startDate"),
                              this->iso8601(since));
                 }
                 if (isTrue(isTrue((!isEqual(limit, ccxt::any{}))) &&
                            isTrue((isEqual(outcome, ccxt::any{}))))) {
                   // the outcome scope narrows rows client-side (the venue
                   // filter is per market, not per side) - a server-side page
                   // size would under-fill the filtered result
                   ::setValue(request, std::string("perPage"),
                              this->clampSxbetPerPage(limit));
                 }
                 ccxt::any response = awaitValue(this->sxbetPrivateGetTradesV3(
                     this->extend(request, params)));
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rawTrades =
                     this->safeList(data, std::string("trades"), ccxt::list{});
                 ccxt::any result = ccxt::list{};
                 ccxt::any rawTradesLength = getArrayLength(rawTrades);
                 for (ccxt::any i = 0; isLessThan(i, rawTradesLength);
                      postFixIncrement(i)) {
                   ccxt::any settlement =
                       this->parseSettlement(::getValue(rawTrades, i));
                   if (isTrue(isTrue((isEqual(wantedOutcomeId, ccxt::any{}))) ||
                              isTrue((isEqual(
                                  this->safeString(settlement,
                                                   std::string("outcomeId")),
                                  wantedOutcomeId))))) {
                     arrayPush(result, settlement);
                   }
                 }
                 return result;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSettlement
   * @description parses one settled GET /trades-v3 row into the unified
   * prediction settlement shape. the raw `outcome` field carries the winner, 1
   * or 2, with 0 for a voided market, and the full payout of a winning bet is
   * stake / odds (the implied probability the bettor received)
   * @param {object} trade the raw settled sx.bet trade
   * @param {object} [market] a resolved outcome/market hint
   * @returns {object} a prediction settlement structure
   */
  virtual ccxt::any parseSettlement(ccxt::any trade,
                                    ccxt::any market = ccxt::any{}) {
    //
    //     TradeV3 row with a settlement sub-object:
    //     {
    //         "tradeId": "0xac6b...", "marketHash": "0x1fec...",
    //         "isBettingOutcomeOne": false, "totalStake": "1000000",
    //         "totalReturn": "2500000", "weightedAverageOdds":
    //         "40000000000000000000", "status": "SETTLED", "betTime":
    //         "2026-07-31T18:47:09.577Z", "settlement": { "outcome": 2,
    //         "settleReturnAmount": "2500000",
    //                         "settleFeeAmount": "0", "settleCeRefundAmount":
    //                         "0", "settleDate": "2026-08-01T00:10:00.000Z" }
    //     }
    //
    ccxt::any marketHash =
        this->safeString(trade, std::string("marketHash"), std::string(""));
    ccxt::any isBettingOutcomeOne =
        this->safeBool(trade, std::string("isBettingOutcomeOne"), true);
    ccxt::any outcomeId = ccxt::any{};
    if (isTrue(isBettingOutcomeOne)) {
      outcomeId = marketHash;
    } else {
      outcomeId = (add(marketHash, std::string("-2")));
    }
    ccxt::any outcomeObj = this->safeOutcome(outcomeId, market);
    ccxt::any settlement =
        this->safeDict(trade, std::string("settlement"), ccxt::dict{});
    ccxt::any winner = this->safeInteger(settlement, std::string("outcome"));
    ccxt::any isVoid = (isEqual(winner, 0));
    ccxt::any heldNumber =
        (isTrue((isBettingOutcomeOne)) ? ccxt::any(1) : ccxt::any(2));
    ccxt::any won = ccxt::any{};
    if (isTrue(isTrue((!isEqual(winner, ccxt::any{}))) && !isTrue(isVoid))) {
      won = (isEqual(winner, heldNumber));
    }
    ccxt::any usdcDecimals = std::string("1000000");
    ccxt::any stake = ccxt::Precise::stringDiv(
        this->safeString(trade, std::string("totalStake"), std::string("0")),
        usdcDecimals, 6);
    ccxt::any payout = ccxt::Precise::stringDiv(
        this->safeString(settlement, std::string("settleReturnAmount"),
                         std::string("0")),
        usdcDecimals, 6);
    ccxt::any pnl = ccxt::Precise::stringSub(payout, stake);
    // resolve the winning side's human label through the cached market when
    // available
    ccxt::any resultLabel = ccxt::any{};
    if (isTrue(isVoid)) {
      resultLabel = std::string("VOID");
    } else if (isTrue(!isEqual(winner, ccxt::any{}))) {
      ccxt::any info =
          this->safeDict(outcomeObj, std::string("info"), ccxt::dict{});
      ccxt::any labelKey = std::string("outcomeTwoName");
      if (isTrue(isEqual(winner, 1))) {
        labelKey = std::string("outcomeOneName");
      }
      resultLabel =
          this->safeString(info, labelKey, this->numberToString(winner));
    }
    ccxt::any timestamp = this->parse8601(
        this->safeString(settlement, std::string("settleDate")));
    ccxt::any settlePrice = ccxt::any{};
    if (isTrue(!isEqual(won, ccxt::any{}))) {
      settlePrice =
          (isTrue((isEqual(won, true))) ? ccxt::any(1) : ccxt::any(0));
    }
    return ccxt::dict{
        {std::string("info"), trade},
        {std::string("id"), this->safeString(trade, std::string("tradeId"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("outcome"),
         this->safeString(outcomeObj, std::string("outcome"), outcomeId)},
        {std::string("outcomeId"),
         this->safeString(outcomeObj, std::string("outcomeId"), outcomeId)},
        {std::string("market"),
         this->safeString(outcomeObj, std::string("market"))},
        {std::string("event"), ccxt::any{}},
        {std::string("result"), resultLabel},
        {std::string("won"), won},
        {std::string("amount"), this->parseNumber(stake)},
        {std::string("price"), settlePrice},
        {std::string("cost"), this->parseNumber(stake)},
        {std::string("payout"), this->parseNumber(payout)},
        {std::string("pnl"), this->parseNumber(pnl)},
    };
  }

  /**
   * @ignore
   * @method
   * @name sxbet#fetchSxbetBookSnapshot
   * @description fetches the v3 aggregated order book snapshot of one market
   * ({outcomeOne, outcomeTwo, version} price levels)
   * @see https://docs.sx.bet/api-reference/get-orderbook-snapshot
   * @param {string} marketHash the market hash
   * @returns {object} the raw snapshot data
   */
  virtual std::shared_future<ccxt::any>
  fetchSxbetBookSnapshot(ccxt::any marketHash) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any request = ccxt::dict{
                            {std::string("marketHash"), marketHash},
                        };
                        ccxt::any response = awaitValue(
                            this->sxbetPublicGetOrderbookV3Snapshot(request));
                        return this->safeDict(response, std::string("data"),
                                              ccxt::dict{});
                      })
        .share();
  }

  /**
   * @method
   * @name sxbet#fetchTicker
   * @description fetches the current best resting odds for a single sx.bet
   * outcome. sx.bet is a peer-to-peer odds book (no matched-trade tape or
   * candles), so bid/ask are the best (highest) percentageOdds resting on this
   * outcome's own side and its mirror (1 - best percentageOdds resting on the
   * opposite outcome)
   * @see https://docs.sx.bet/api-reference/get-orderbook-snapshot
   * @param {string} outcome unified outcome handle or outcomeId (marketHash or
   * marketHash + '-2')
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction ticker
   * structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any outcome, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        awaitValue(this->loadOutcome(outcome));
                        ccxt::any outcomeObj = this->outcome(outcome);
                        ccxt::any marketHash = this->safeString(
                            ::getValue(outcomeObj, std::string("info")),
                            std::string("marketHash"));
                        // the book snapshot is public and carries the same top
                        // of book - the batched best-odds route needs an
                        // apiKey, so it only pays off for the multi-market path
                        ccxt::any snapshot = awaitValue(
                            this->fetchSxbetBookSnapshot(marketHash));
                        ccxt::any raw =
                            this->parseSxbetSnapshotBestOdds(snapshot);
                        return this->parsePredictionTicker(raw, outcomeObj);
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#fetchSxbetBestOdds
   * @description fetches the best resting level of both sides for a set of
   * markets in one request
   * @see https://docs.sx.bet/api-reference/get-best-odds-v3
   * @param {string[]} marketHashes the market hashes to query, at most 100 per
   * call
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} the raw bestOdds rows ({marketHash, outcomeOne,
   * outcomeTwo})
   */
  virtual std::shared_future<ccxt::any>
  fetchSxbetBestOdds(ccxt::any marketHashes, ccxt::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any request = ccxt::dict{
                            {std::string("marketHashes"),
                             join(marketHashes, std::string(","))},
                        };
                        ccxt::any response =
                            awaitValue(this->sxbetPrivateGetOrdersV3OddsBest(
                                this->extend(request, params)));
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->safeList(data, std::string("bestOdds"),
                                              ccxt::list{});
                      })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetSnapshotBestOdds
   * @description reduces a v3 book snapshot to the legacy best-odds shape the
   * ticker parser consumes ({marketHash, outcomeOne: {percentageOdds},
   * outcomeTwo: {percentageOdds}})
   * @param {object} snapshot the raw snapshot data
   * @returns {object} the best-odds shaped dict
   */
  virtual ccxt::any parseSxbetSnapshotBestOdds(ccxt::any snapshot) {
    // levels arrive sorted best-first; the best level's odds mirror the v2
    // best-odds fields
    ccxt::any oneLevels =
        this->safeList(snapshot, std::string("outcomeOne"), ccxt::list{});
    ccxt::any twoLevels =
        this->safeList(snapshot, std::string("outcomeTwo"), ccxt::list{});
    ccxt::any bestOne = this->safeDict(oneLevels, 0, ccxt::dict{});
    ccxt::any bestTwo = this->safeDict(twoLevels, 0, ccxt::dict{});
    return ccxt::dict{
        {std::string("marketHash"),
         this->safeString(snapshot, std::string("marketHash"))},
        {std::string("outcomeOne"),
         ccxt::dict{
             {std::string("percentageOdds"),
              this->safeString(bestOne, std::string("percentageOdds"))},
         }},
        {std::string("outcomeTwo"),
         ccxt::dict{
             {std::string("percentageOdds"),
              this->safeString(bestTwo, std::string("percentageOdds"))},
         }},
    };
  }

  /**
   * @method
   * @name sxbet#fetchTickers
   * @description fetches the current best resting odds for multiple sx.bet
   * outcomes, one book snapshot per market
   * @see https://docs.sx.bet/api-reference/get-orderbook-snapshot
   * @param {string[]} outcomes unified outcomes - required: sx.bet has
   * thousands of markets and no endpoint returning all of them at once
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [prediction ticker
   * structures](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
   * indexed by outcome
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any outcomes = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(outcomes, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(" fetchTickers() requires an outcomes "
                                   "argument - sx.bet has thousands of markets "
                                   "and serves best odds per market list"))));
                 }
                 ccxt::any outcomesList = outcomes;
                 ccxt::any outcomesLength = getArrayLength(outcomesList);
                 ccxt::any hashesOrder = ccxt::list{};
                 ccxt::any seenHashes = ccxt::dict{};
                 for (ccxt::any i = 0; isLessThan(i, outcomesLength);
                      postFixIncrement(i)) {
                   awaitValue(this->loadOutcome(::getValue(outcomesList, i)));
                   ccxt::any outcomeObj =
                       this->outcome(::getValue(outcomesList, i));
                   ccxt::any marketHash = this->safeString(
                       ::getValue(outcomeObj, std::string("info")),
                       std::string("marketHash"), std::string(""));
                   if (isTrue(isEqual(this->safeBool(seenHashes, marketHash),
                                      ccxt::any{}))) {
                     ::setValue(seenHashes, marketHash, true);
                     arrayPush(hashesOrder, marketHash);
                   }
                 }
                 // both outcomes of a market share one row, and the venue takes
                 // at most 100 hashes per call. the batched route is
                 // apiKey-authenticated, so fall back to the public per-market
                 // snapshots when the instance carries no credentials
                 ccxt::any rowsByHash = ccxt::dict{};
                 ccxt::any hashesLength = getArrayLength(hashesOrder);
                 ccxt::any hasApiKey =
                     !isTrue(this->isEmptyString(this->apiKey));
                 if (!isTrue(hasApiKey)) {
                   for (ccxt::any i = 0; isLessThan(i, hashesLength);
                        postFixIncrement(i)) {
                     ccxt::any marketHash = ::getValue(hashesOrder, i);
                     ccxt::any snapshot =
                         awaitValue(this->fetchSxbetBookSnapshot(marketHash));
                     ::setValue(rowsByHash, marketHash,
                                this->parseSxbetSnapshotBestOdds(snapshot));
                   }
                   return this->parseSxbetTickersByHash(outcomesList,
                                                        rowsByHash);
                 }
                 ccxt::any chunkSize = this->safeInteger(
                     this->options, std::string("bestOddsBatchSize"), 100);
                 ccxt::any chunkCount = this->parseToInt(
                     divide(this->sum(hashesLength, subtract(chunkSize, 1)),
                            chunkSize));
                 for (ccxt::any c = 0; isLessThan(c, chunkCount);
                      postFixIncrement(c)) {
                   ccxt::any start = multiply(c, chunkSize);
                   ccxt::any end = add(start, chunkSize);
                   if (isTrue(isGreaterThan(end, hashesLength))) {
                     end = hashesLength;
                   }
                   ccxt::any chunk = this->arraySlice(hashesOrder, start, end);
                   ccxt::any rows =
                       awaitValue(this->fetchSxbetBestOdds(chunk, params));
                   ccxt::any rowsLength = getArrayLength(rows);
                   for (ccxt::any j = 0; isLessThan(j, rowsLength);
                        postFixIncrement(j)) {
                     ccxt::any row = ::getValue(rows, j);
                     ccxt::any rowHash =
                         this->safeString(row, std::string("marketHash"));
                     if (isTrue(!isEqual(rowHash, ccxt::any{}))) {
                       ::setValue(rowsByHash, rowHash, row);
                     }
                   }
                 }
                 return this->parseSxbetTickersByHash(outcomesList, rowsByHash);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetTickersByHash
   * @description assembles the unified tickers dict from best-odds shaped rows
   * keyed by market hash
   * @param {string[]} outcomesList the requested unified outcomes
   * @param {object} rowsByHash best-odds rows indexed by market hash
   * @returns {object} a dictionary of [prediction ticker
   * structures](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
   * indexed by outcome
   */
  virtual ccxt::any parseSxbetTickersByHash(ccxt::any outcomesList,
                                            ccxt::any rowsByHash) {
    ccxt::any result = ccxt::dict{};
    ccxt::any outcomesLength = getArrayLength(outcomesList);
    for (ccxt::any i = 0; isLessThan(i, outcomesLength); postFixIncrement(i)) {
      ccxt::any outcomeObj = this->outcome(::getValue(outcomesList, i));
      ccxt::any marketHash =
          this->safeString(::getValue(outcomeObj, std::string("info")),
                           std::string("marketHash"), std::string(""));
      ccxt::any raw = this->safeDict(rowsByHash, marketHash);
      if (isTrue(isEqual(raw, ccxt::any{}))) {
        continue;
      }
      ccxt::any ticker = this->parsePredictionTicker(raw, outcomeObj);
      ccxt::any sym = this->safeString(ticker, std::string("outcome"));
      if (isTrue(!isEqual(sym, ccxt::any{}))) {
        ::setValue(result, sym, ticker);
      }
    }
    return result;
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parsePredictionTicker
   * @description parses one /orders/odds/best entry into a unified ticker for
   * one side of the market
   * @param {object} raw one bestOdds entry ({ marketHash, baseToken,
   * outcomeOne: { percentageOdds, updatedAt }, outcomeTwo: {...} })
   * @param {object} [market] the outcome object the ticker belongs to
   * @returns {object} a [prediction ticker
   * structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
   */
  ccxt::any parsePredictionTicker(ccxt::any raw,
                                  ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "marketHash":
    //         "0x48ce0ef287c59fb3bb3ca6deb80de0d5791eb761ea8e16d6f03c8e93ef28d1de",
    //         "baseToken": "0x6629Ce1Cf35Cc1329ebB4F63202F3f197b3F050B",
    //         "outcomeOne": { "percentageOdds": "50250000000000000000",
    //         "updatedAt": 1785697831141 }, "outcomeTwo": { "percentageOdds":
    //         "48000000000000000000", "updatedAt": 1785699649869 }
    //     }
    //
    ccxt::any marketAny = market;
    ccxt::any outcomeObj = this->safeOutcome(
        this->safeString(marketAny, std::string("outcome")), marketAny);
    ccxt::any outcomeId =
        this->safeString(outcomeObj, std::string("outcomeId"));
    ccxt::any marketHash = this->safeString(raw, std::string("marketHash"));
    ccxt::any isOutcomeOne = (isEqual(outcomeId, marketHash));
    ccxt::any outcomeOneOdds =
        this->safeDict(raw, std::string("outcomeOne"), ccxt::dict{});
    ccxt::any outcomeTwoOdds =
        this->safeDict(raw, std::string("outcomeTwo"), ccxt::dict{});
    ccxt::any ownOdds = outcomeTwoOdds;
    if (isTrue(isOutcomeOne)) {
      ownOdds = outcomeOneOdds;
    }
    ccxt::any oppositeOdds = outcomeOneOdds;
    if (isTrue(isOutcomeOne)) {
      oppositeOdds = outcomeTwoOdds;
    }
    // percentageOdds is the maker's own implied probability * 1e20 (sx.bet
    // protocol format); the opposite side's best resting maker mirrors into
    // this outcome's ask via 1 - p
    ccxt::any oneDenom = std::string("100000000000000000000");
    ccxt::any ownPercentage =
        this->safeString(ownOdds, std::string("percentageOdds"));
    ccxt::any oppositePercentage =
        this->safeString(oppositeOdds, std::string("percentageOdds"));
    ccxt::any bid = (isTrue((!isEqual(ownPercentage, ccxt::any{})))
                         ? ccxt::any(this->parseNumber(ccxt::Precise::stringDiv(
                               ownPercentage, oneDenom)))
                         : ccxt::any(ccxt::any{}));
    ccxt::any ask =
        (isTrue((!isEqual(oppositePercentage, ccxt::any{})))
             ? ccxt::any(this->parseNumber(ccxt::Precise::stringSub(
                   std::string("1"),
                   ccxt::Precise::stringDiv(oppositePercentage, oneDenom))))
             : ccxt::any(ccxt::any{}));
    ccxt::any updatedAt = this->safeInteger(ownOdds, std::string("updatedAt"));
    ccxt::any now = this->milliseconds();
    ccxt::any timestamp =
        (isTrue((!isEqual(updatedAt, ccxt::any{}))) ? ccxt::any(updatedAt)
                                                    : ccxt::any(now));
    ccxt::any average = ccxt::any{};
    if (isTrue(isTrue((!isEqual(bid, ccxt::any{}))) &&
               isTrue((!isEqual(ask, ccxt::any{}))))) {
      average = this->parseNumber(ccxt::Precise::stringDiv(
          ccxt::Precise::stringAdd(this->numberToString(bid),
                                   this->numberToString(ask)),
          std::string("2")));
    }
    return this->safePredictionTicker(
        ccxt::dict{
            {std::string("outcome"),
             this->safeString(outcomeObj, std::string("outcome"))},
            {std::string("outcomeId"), outcomeId},
            {std::string("label"),
             this->safeString(outcomeObj, std::string("label"))},
            {std::string("market"),
             this->safeString(outcomeObj, std::string("market"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"), ccxt::any{}},
            {std::string("low"), ccxt::any{}},
            {std::string("bid"), bid},
            {std::string("bidVolume"), ccxt::any{}},
            {std::string("ask"), ask},
            {std::string("askVolume"), ccxt::any{}},
            {std::string("open"), ccxt::any{}},
            {std::string("close"), bid},
            {std::string("last"), bid},
            {std::string("change"), ccxt::any{}},
            {std::string("percentage"), ccxt::any{}},
            {std::string("average"), average},
            {std::string("baseVolume"), ccxt::any{}},
            {std::string("quoteVolume"), ccxt::any{}},
            {std::string("info"), raw},
        },
        market);
  }

  /**
   * @method
   * @name sxbet#fetchOrderBook
   * @description fetches the resting maker order book for a single sx.bet
   * outcome. bids are maker orders already betting on this outcome (priced at
   * each maker's own implied probability, sized by their remaining stake); asks
   * mirror the opposite outcome's maker orders (price = 1 - their implied
   * probability, sized by how much a taker could bet against them, per sx.bet's
   * remaining-taker-space formula) — the same YES/NO-style mirrored
   * construction used across this codebase's other binary prediction venues
   * @see https://docs.sx.bet/api-reference/get-orderbook-snapshot
   * @param {string} outcome unified outcome handle or outcomeId
   * @param {int} [limit] the maximum number of bids/asks to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction order book
   * structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any outcome, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any marketHash = this->safeString(
                     ::getValue(outcomeObj, std::string("info")),
                     std::string("marketHash"));
                 ccxt::any outcomeId =
                     this->safeString(outcomeObj, std::string("outcomeId"));
                 ccxt::any isOutcomeOne = (isEqual(outcomeId, marketHash));
                 ccxt::any request = ccxt::dict{
                     {std::string("marketHash"), marketHash},
                 };
                 ccxt::any response =
                     awaitValue(this->sxbetPublicGetOrderbookV3Snapshot(
                         this->extend(request, params)));
                 ccxt::any snapshot = this->safeDict(
                     response, std::string("data"), ccxt::dict{});
                 ccxt::any sides =
                     this->parseSxbetV3BookSides(snapshot, isOutcomeOne);
                 ccxt::any sortedBids =
                     this->safeList(sides, std::string("bids"), ccxt::list{});
                 ccxt::any sortedAsks =
                     this->safeList(sides, std::string("asks"), ccxt::list{});
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ccxt::any bidsLength = getArrayLength(sortedBids);
                   ccxt::any bidsEnd = limit;
                   if (isTrue(isGreaterThan(bidsEnd, bidsLength))) {
                     bidsEnd = bidsLength;
                   }
                   sortedBids = this->arraySlice(sortedBids, 0, bidsEnd);
                   ccxt::any asksLength = getArrayLength(sortedAsks);
                   ccxt::any asksEnd = limit;
                   if (isTrue(isGreaterThan(asksEnd, asksLength))) {
                     asksEnd = asksLength;
                   }
                   sortedAsks = this->arraySlice(sortedAsks, 0, asksEnd);
                 }
                 ccxt::any timestamp = this->milliseconds();
                 return this->safePredictionOrderBook(
                     ccxt::dict{
                         {std::string("outcome"),
                          this->safeString(outcomeObj, std::string("outcome"),
                                           outcome)},
                         {std::string("bids"), sortedBids},
                         {std::string("asks"), sortedAsks},
                         {std::string("timestamp"), timestamp},
                         {std::string("datetime"), this->iso8601(timestamp)},
                         {std::string("nonce"), ccxt::any{}},
                     },
                     outcomeObj);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetV3BookSides
   * @description converts a v3 aggregated book snapshot into sorted [price,
   * amount] bid/ask levels for one outcome; shared by fetchOrderBook and the
   * websocket book handler
   * @param {object} snapshot the raw snapshot ({outcomeOne, outcomeTwo} level
   * lists of {percentageOdds, size})
   * @param {boolean} isOutcomeOne whether the book is built for the market's
   * outcome one
   * @returns {object} a dict with sorted 'bids' and 'asks' lists
   */
  virtual ccxt::any parseSxbetV3BookSides(ccxt::any snapshot,
                                          ccxt::any isOutcomeOne) {
    ccxt::any oneDenom = std::string("100000000000000000000");
    ccxt::any usdcDecimals = std::string("1000000");
    ccxt::any ownLevels =
        (isTrue((isOutcomeOne))
             ? ccxt::any(this->safeList(snapshot, std::string("outcomeOne"),
                                        ccxt::list{}))
             : ccxt::any(this->safeList(snapshot, std::string("outcomeTwo"),
                                        ccxt::list{})));
    ccxt::any oppositeLevels =
        (isTrue((isOutcomeOne))
             ? ccxt::any(this->safeList(snapshot, std::string("outcomeTwo"),
                                        ccxt::list{}))
             : ccxt::any(this->safeList(snapshot, std::string("outcomeOne"),
                                        ccxt::list{})));
    ccxt::any bids = ccxt::list{};
    ccxt::any ownLevelsLength = getArrayLength(ownLevels);
    for (ccxt::any i = 0; isLessThan(i, ownLevelsLength); postFixIncrement(i)) {
      ccxt::any level = this->safeDict(ownLevels, i);
      ccxt::any percentageOdds =
          this->safeString(level, std::string("percentageOdds"));
      ccxt::any size =
          this->safeString(level, std::string("size"), std::string("0"));
      ccxt::any price =
          this->parseNumber(ccxt::Precise::stringDiv(percentageOdds, oneDenom));
      ccxt::any amount =
          this->parseNumber(ccxt::Precise::stringDiv(size, usdcDecimals, 6));
      arrayPush(bids, ccxt::list{price, amount});
    }
    ccxt::any asks = ccxt::list{};
    ccxt::any oppositeLevelsLength = getArrayLength(oppositeLevels);
    for (ccxt::any i = 0; isLessThan(i, oppositeLevelsLength);
         postFixIncrement(i)) {
      ccxt::any level = this->safeDict(oppositeLevels, i);
      ccxt::any percentageOdds =
          this->safeString(level, std::string("percentageOdds"));
      ccxt::any size =
          this->safeString(level, std::string("size"), std::string("0"));
      // the opposite side's resting stake mirrors into this outcome's ask - the
      // price is the complement, and the takeable amount follows the
      // remaining-taker-space formula
      ccxt::any price = this->parseNumber(ccxt::Precise::stringSub(
          std::string("1"),
          ccxt::Precise::stringDiv(percentageOdds, oneDenom)));
      ccxt::any ratio = ccxt::Precise::stringDiv(oneDenom, percentageOdds, 12);
      ccxt::any remainingTaker =
          ccxt::Precise::stringSub(ccxt::Precise::stringMul(size, ratio), size);
      ccxt::any amount = this->parseNumber(
          ccxt::Precise::stringDiv(remainingTaker, usdcDecimals, 6));
      arrayPush(asks, ccxt::list{price, amount});
    }
    return ccxt::dict{
        {std::string("bids"), this->sortBy(bids, 0, true)},
        {std::string("asks"), this->sortBy(asks, 0)},
    };
  }

  virtual ccxt::any requestId(ccxt::any url) {
    ccxt::any existing =
        this->safeValue(this->options, std::string("requestId"));
    if (isTrue(isEqual(existing, ccxt::any{}))) {
      ::setValue(this->options, std::string("requestId"),
                 this->createSafeDictionary());
    }
    ccxt::any options = ::getValue(this->options, std::string("requestId"));
    ccxt::any previousValue = this->safeInteger(options, url, 0);
    ccxt::any newValue = this->sum(previousValue, 1);
    if (isTrue(!isEqual(url, ccxt::any{}))) {
      ::setValue(::getValue(this->options, std::string("requestId")), url,
                 newValue);
    }
    return newValue;
  }

  /**
   * @ignore
   * @method
   * @name sxbet#registerSxbetWsRequest
   * @description tracks an outgoing Centrifugo connect/subscribe command by its
   * request id, so an error reply can be correlated back to the awaiting future
   * and its registered subscription hash (see handleCentrifugoFrame)
   * @param {int} requestId the id sent with the command
   * @param {string} messageHash the future hash the caller awaits
   * @param {string} subscription the subscription hash registered by watch()
   * ('connect' or the channel name)
   */
  virtual void registerSxbetWsRequest(ccxt::any requestId,
                                      ccxt::any messageHash,
                                      ccxt::any subscription) {
    ccxt::any existing =
        this->safeDict(this->options, std::string("wsPendingRequests"));
    if (isTrue(isEqual(existing, ccxt::any{}))) {
      ::setValue(this->options, std::string("wsPendingRequests"),
                 this->createSafeDictionary());
    }
    ccxt::any requestIdString = this->numberToString(requestId);
    ::setValue(::getValue(this->options, std::string("wsPendingRequests")),
               requestIdString,
               ccxt::dict{
                   {std::string("messageHash"), messageHash},
                   {std::string("subscription"), subscription},
               });
  }

  /**
   * @ignore
   * @method
   * @name sxbet#fetchSxbetRealtimeToken
   * @description fetches the short-lived Centrifugo connection token from the
   * relayer; requires the apiKey credential (X-Api-Key header)
   * @see https://docs.sx.bet/developers/realtime-initialization
   * @returns {string} the JWT connection token
   */
  virtual std::shared_future<ccxt::any> fetchSxbetRealtimeToken() {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->apiKey, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " websocket streaming requires the apiKey "
                               "credential - the realtime token endpoint "
                               "authenticates with the X-Api-Key header"))));
                 }
                 ccxt::any response = awaitValue(
                     this->sxbetPrivateGetUserRealtimeTokenV3ApiKey());
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 return this->safeString2(
                     data, std::string("token"), std::string("realtimeToken"),
                     this->safeString(response, std::string("token")));
               })
        .share();
  }

  virtual std::shared_future<ccxt::any> connectSxbetCentrifugo(ccxt::any url) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // Centrifugo requires a token-carrying connect command before
                 // any subscribe. This sends it once per connection and
                 // resolves when the connect reply arrives (see
                 // handleCentrifugoFrame). The base clears ::getValue(client,
                 // std::string("subscriptions")) on reconnect, so an absent
                 // 'connect' marker means a fresh handshake.
                 ccxt::any client = this->client(url);
                 ccxt::any connectSent = this->safeValue(
                     ::getValue(client, std::string("subscriptions")),
                     std::string("connect"));
                 if (isTrue(isEqual(connectSent, ccxt::any{}))) {
                   ::setValue(this->options, std::string("wsConnected"), false);
                   ccxt::any token =
                       awaitValue(this->fetchSxbetRealtimeToken());
                   ccxt::any requestId = this->requestId(url);
                   this->registerSxbetWsRequest(
                       requestId, std::string("centrifugoConnected"),
                       std::string("connect"));
                   ccxt::any connectMsg = ccxt::dict{
                       {std::string("connect"),
                        ccxt::dict{
                            {std::string("token"), token},
                            {std::string("name"), std::string("ccxt")},
                        }},
                       {std::string("id"), requestId},
                   };
                   return awaitValue(
                       this->watch(url, std::string("centrifugoConnected"),
                                   connectMsg, std::string("connect")));
                 }
                 if (isTrue(this->safeBool(
                         this->options, std::string("wsConnected"), false))) {
                   // the connect reply already arrived on the current
                   // connection - safe to subscribe immediately
                   return ccxt::any{};
                 }
                 // connect is in flight, sent by a concurrent subscribe - wait
                 // on the shared reply future
                 return awaitValue(::wsClientFuture(
                     client, std::string("centrifugoConnected")));
               })
        .share();
  }

  virtual std::shared_future<ccxt::any> pong(ccxt::any client,
                                             ccxt::any message = ccxt::any{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        // Centrifugo server pings are empty frames; reply with
                        // the same empty frame to keep the link alive
                        awaitValue(::wsClientSend(client, std::string("{}")));
                        return ccxt::any{};
                      })
        .share();
  }

  virtual std::shared_future<ccxt::any>
  subscribeSxbetChannel(ccxt::any messageHash, ccxt::any channel) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any url = this->safeString(
                            ::getValue(this->urls, std::string("api")),
                            std::string("ws"));
                        // finish the connect handshake first so the subscribe
                        // frame follows the connect reply
                        awaitValue(this->connectSxbetCentrifugo(url));
                        ccxt::any requestId = this->requestId(url);
                        this->registerSxbetWsRequest(requestId, messageHash,
                                                     channel);
                        ccxt::any subscribeMsg = ccxt::dict{
                            {std::string("subscribe"),
                             ccxt::dict{
                                 {std::string("channel"), channel},
                             }},
                            {std::string("id"), requestId},
                        };
                        return awaitValue(this->watch(url, messageHash,
                                                      subscribeMsg, channel));
                      })
        .share();
  }

  void handleMessage(ccxt::any client, ccxt::any message) override {
    // Centrifugo packs several commands per frame joined by newlines; a
    // multi-command frame fails the base JSON.parse and arrives here in
    // raw-string form, a single command arrives already parsed
    if (isTrue(isString(message))) {
      ccxt::any lines = split(message, std::string("\n"));
      ccxt::any linesLength = getArrayLength(lines);
      for (ccxt::any i = 0; isLessThan(i, linesLength); postFixIncrement(i)) {
        ccxt::any line = ::getValue(lines, i);
        if (isTrue(isGreaterThan(getStringLength(line), 0))) {
          ccxt::any parsed = parseJson(line);
          this->handleCentrifugoFrame(client, parsed);
        }
      }
      return;
    }
    this->handleCentrifugoFrame(client, message);
  }

  virtual void handleCentrifugoFrame(ccxt::any client, ccxt::any msg) {
    ccxt::any keys = getObjectKeys(msg);
    ccxt::any keysLength = getArrayLength(keys);
    if (isTrue(isEqual(keysLength, 0))) {
      this->spawn(std::string("pong"), client, msg);
      return;
    }
    ccxt::any requestIdString = this->safeString(msg, std::string("id"));
    ccxt::any pendingRequests = this->safeDict(
        this->options, std::string("wsPendingRequests"), ccxt::dict{});
    ccxt::any pendingEntry = this->safeDict(pendingRequests, requestIdString);
    ccxt::any errorReply = this->safeDict(msg, std::string("error"));
    if (isTrue(!isEqual(errorReply, ccxt::any{}))) {
      // a rejected connect (bad or expired realtime token) or subscribe
      // (unauthorized or unknown channel) - fail the awaiting future and clear
      // the subscription hash that watch() registered at send time, so the next
      // call re-sends the command instead of waiting forever behind a marker
      // that will never be served
      ExchangeError error =
          ExchangeError(add(add(this->id, std::string(" ")), this->json(msg)));
      if (isTrue(!isEqual(pendingEntry, ccxt::any{}))) {
        ccxt::any failedHash =
            this->safeString(pendingEntry, std::string("messageHash"));
        ccxt::any subscription =
            this->safeString(pendingEntry, std::string("subscription"));
        if (isTrue(isEqual(subscription, std::string("connect")))) {
          ::setValue(this->options, std::string("wsConnected"), false);
        }
        if (isTrue(
                isTrue((!isEqual(subscription, ccxt::any{}))) &&
                isTrue((inOp(::getValue(client, std::string("subscriptions")),
                             subscription))))) {
          deleteKey(::getValue(client, std::string("subscriptions")),
                    subscription);
        }
        ::setValue(this->options, std::string("wsPendingRequests"),
                   this->omit(pendingRequests, requestIdString));
        this->reject(error, failedHash);
      } else {
        // an error that cannot be correlated to one command fails the whole
        // connection
        this->reject(error);
      }
      return;
    }
    if (isTrue(!isEqual(pendingEntry, ccxt::any{}))) {
      // a successful command ack - the tracked request has served its purpose
      ::setValue(this->options, std::string("wsPendingRequests"),
                 this->omit(pendingRequests, requestIdString));
    }
    ccxt::any connectReply = this->safeDict(msg, std::string("connect"));
    if (isTrue(!isEqual(connectReply, ccxt::any{}))) {
      // connect acknowledged - unblock connectSxbetCentrifugo so channel
      // subscribes can be sent
      ::setValue(this->options, std::string("wsConnected"), true);
      this->resolve(true, std::string("centrifugoConnected"));
      return;
    }
    ccxt::any push = this->safeDict(msg, std::string("push"));
    if (isTrue(isEqual(push, ccxt::any{}))) {
      return;
    }
    ccxt::any channel = this->safeString(push, std::string("channel"));
    if (isTrue(isEqual(channel, ccxt::any{}))) {
      return;
    }
    ccxt::any pub = this->safeDict(push, std::string("pub"), ccxt::dict{});
    ccxt::any data = this->safeValue(pub, std::string("data"));
    if (isTrue(isEqual(data, ccxt::any{}))) {
      return;
    }
    // rows arrive either shaped like one object or like an array of objects -
    // normalize to a list
    ccxt::any rows = ccxt::list{};
    if (isTrue(isArray(data))) {
      rows = data;
    } else {
      rows = ccxt::list{data};
    }
    ccxt::any parts = split(channel, std::string(":"));
    ccxt::any channelType = this->safeString(parts, 0);
    if (isTrue(isEqual(channelType, std::string("orderbook_v3")))) {
      this->handleOrderBook(client, rows);
    } else if (isTrue(isEqual(channelType, std::string("best_odds_v3")))) {
      this->handleTicker(client, rows);
    } else if (isTrue(isEqual(channelType, std::string("recent_trades_v3")))) {
      this->handleTrades(client, rows);
    } else if (isTrue(isEqual(channelType, std::string("account")))) {
      // per-account channels: account:orders_v3_#addr / account:fills_v3_#addr
      if (isTrue(isGreaterThanOrEqual(
              getIndexOf(channel, std::string("orders_v3")), 0))) {
        this->handleOrder(client, rows);
      } else if (isTrue(isGreaterThanOrEqual(
                     getIndexOf(channel, std::string("fills_v3")), 0))) {
        this->handleMyTrade(client, rows);
      }
    }
  }

  /**
   * @method
   * @name sxbet#watchOrderBook
   * @description streams the order book of an outcome - the v3 channel
   * publishes the entire aggregated book on every update with a monotonic
   * version, so each message replaces the held book
   * @see https://docs.sx.bet/api-reference/channel-orderbook-v3
   * @param {string} outcome unified outcome or outcome token id
   * @param {int} [limit] the maximum number of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction order book
   * structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
   */
  std::shared_future<ccxt::any>
  watchOrderBook(ccxt::any outcome, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any sym =
                     this->safeString(outcomeObj, std::string("outcome"));
                 ccxt::any marketHash = this->safeString(
                     ::getValue(outcomeObj, std::string("info")),
                     std::string("marketHash"));
                 ccxt::any channel =
                     add(std::string("orderbook_v3:"), marketHash);
                 ccxt::any messageHash = add(std::string("orderbook::"), sym);
                 ccxt::any url = this->safeString(
                     ::getValue(this->urls, std::string("api")),
                     std::string("ws"));
                 awaitValue(this->connectSxbetCentrifugo(url));
                 ccxt::any client = this->client(url);
                 ccxt::any isNewSubscription = isEqual(
                     this->safeValue(
                         ::getValue(client, std::string("subscriptions")),
                         channel),
                     ccxt::any{});
                 if (isTrue(isEqual(this->safeValue(this->orderbooks, sym),
                                    ccxt::any{}))) {
                   // seed from the REST snapshot so the book is served before
                   // the first publication
                   ccxt::any watchedBooks = this->safeDict(
                       this->options, std::string("wsWatchedBooks"));
                   if (isTrue(isEqual(watchedBooks, ccxt::any{}))) {
                     ::setValue(this->options, std::string("wsWatchedBooks"),
                                this->createSafeDictionary());
                   }
                   ::setValue(
                       ::getValue(this->options, std::string("wsWatchedBooks")),
                       sym, marketHash);
                   ccxt::any snapshot =
                       awaitValue(this->fetchSxbetBookSnapshot(marketHash));
                   this->applySxbetWsSnapshot(snapshot);
                   if (isTrue(isEqual(this->safeValue(this->orderbooks, sym),
                                      ccxt::any{}))) {
                     ccxt::any emptyBook = this->orderBook(ccxt::dict{});
                     ::setValue(this->orderbooks, sym, emptyBook);
                   }
                 }
                 ccxt::any requestId = this->requestId(url);
                 this->registerSxbetWsRequest(requestId, messageHash, channel);
                 ccxt::any subscribeMsg = ccxt::dict{
                     {std::string("subscribe"),
                      ccxt::dict{
                          {std::string("channel"), channel},
                      }},
                     {std::string("id"), requestId},
                 };
                 ccxt::any future =
                     this->watch(url, messageHash, subscribeMsg, channel);
                 if (isTrue(isNewSubscription)) {
                   // return the freshly-seeded book immediately instead of
                   // blocking until the next publication
                   this->resolve(this->safeValue(this->orderbooks, sym),
                                 messageHash);
                 }
                 ccxt::any orderbook = awaitValue(future);
                 return ::wsLimit(orderbook);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#applySxbetWsSnapshot
   * @description applies one full v3 book publication ({marketHash, version,
   * outcomeOne, outcomeTwo}) to every watched outcome of that market, honoring
   * the monotonic version
   * @param {object} snapshot the raw book publication
   * @returns {string[]} the outcome handles whose books were refreshed
   */
  virtual ccxt::any applySxbetWsSnapshot(ccxt::any snapshot) {
    ccxt::any marketHash =
        this->safeString(snapshot, std::string("marketHash"));
    ccxt::any version =
        this->safeString(snapshot, std::string("version"), std::string(""));
    ccxt::any refreshed = ccxt::list{};
    if (isTrue(isEqual(marketHash, ccxt::any{}))) {
      return refreshed;
    }
    ccxt::any versionsAll =
        this->safeDict(this->options, std::string("wsBookVersions"));
    if (isTrue(isEqual(versionsAll, ccxt::any{}))) {
      ::setValue(this->options, std::string("wsBookVersions"),
                 this->createSafeDictionary());
    }
    ccxt::any held = this->safeString(
        ::getValue(this->options, std::string("wsBookVersions")), marketHash,
        std::string(""));
    // versions are fixed-width numeric strings - replace only on a strictly
    // newer publication
    if (isTrue(isTrue((!isEqual(held, std::string("")))) &&
               isTrue((isLessThanOrEqual(version, held))))) {
      return refreshed;
    }
    ::setValue(::getValue(this->options, std::string("wsBookVersions")),
               marketHash, version);
    ccxt::any watchedBooks = this->safeDict(
        this->options, std::string("wsWatchedBooks"), ccxt::dict{});
    ccxt::any watchedSyms = getObjectKeys(watchedBooks);
    ccxt::any timestamp = this->milliseconds();
    ccxt::any watchedSymsLength = getArrayLength(watchedSyms);
    for (ccxt::any i = 0; isLessThan(i, watchedSymsLength);
         postFixIncrement(i)) {
      ccxt::any sym = ::getValue(watchedSyms, i);
      if (isTrue(!isEqual(this->safeString(watchedBooks, sym), marketHash))) {
        continue;
      }
      ccxt::any outcomeObj = this->outcome(sym);
      ccxt::any outcomeId =
          this->safeString(outcomeObj, std::string("outcomeId"));
      ccxt::any isOutcomeOne = (isEqual(outcomeId, marketHash));
      ccxt::any sides = this->parseSxbetV3BookSides(snapshot, isOutcomeOne);
      ccxt::any orderbook = this->safeValue(this->orderbooks, sym);
      if (isTrue(isEqual(orderbook, ccxt::any{}))) {
        orderbook = this->orderBook(ccxt::dict{});
        ::setValue(this->orderbooks, sym, orderbook);
      }
      ccxt::any bookSnapshot = ccxt::dict{
          {std::string("bids"),
           this->safeList(sides, std::string("bids"), ccxt::list{})},
          {std::string("asks"),
           this->safeList(sides, std::string("asks"), ccxt::list{})},
          {std::string("timestamp"), timestamp},
          {std::string("datetime"), this->iso8601(timestamp)},
          {std::string("nonce"), ccxt::any{}},
      };
      ::resetOrderBook(orderbook, bookSnapshot);
      arrayPush(refreshed, sym);
    }
    return refreshed;
  }

  virtual void handleOrderBook(ccxt::any client, ccxt::any rows) {
    //
    //     {
    //         "marketHash": "0x...",
    //         "version": "00100000000000010015000",
    //         "outcomeOne": [ { "percentageOdds": "40000000000000000000",
    //         "size": "1000000" } ], "outcomeTwo": []
    //     }
    //
    ccxt::any rowsLength = getArrayLength(rows);
    for (ccxt::any i = 0; isLessThan(i, rowsLength); postFixIncrement(i)) {
      ccxt::any refreshed = this->applySxbetWsSnapshot(::getValue(rows, i));
      ccxt::any refreshedLength = getArrayLength(refreshed);
      for (ccxt::any j = 0; isLessThan(j, refreshedLength);
           postFixIncrement(j)) {
        ccxt::any sym = ::getValue(refreshed, j);
        this->resolve(this->safeValue(this->orderbooks, sym),
                      add(std::string("orderbook::"), sym));
      }
    }
  }

  /**
   * @method
   * @name sxbet#watchTicker
   * @description streams best-odds updates of an outcome; the venue channel is
   * global, entries are filtered down to the requested outcome's market
   * @see https://docs.sx.bet/api-reference/channel-best-odds-v3
   * @param {string} outcome unified outcome or outcome token id
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [prediction ticker
   * structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
   */
  std::shared_future<ccxt::any>
  watchTicker(ccxt::any outcome, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any sym =
                     this->safeString(outcomeObj, std::string("outcome"));
                 ccxt::any marketHash = this->safeString(
                     ::getValue(outcomeObj, std::string("info")),
                     std::string("marketHash"));
                 ccxt::any messageHash = add(std::string("ticker::"), sym);
                 ccxt::any watchedTickers = this->safeDict(
                     this->options, std::string("wsWatchedTickers"));
                 if (isTrue(isEqual(watchedTickers, ccxt::any{}))) {
                   ::setValue(this->options, std::string("wsWatchedTickers"),
                              this->createSafeDictionary());
                 }
                 ::setValue(
                     ::getValue(this->options, std::string("wsWatchedTickers")),
                     sym, marketHash);
                 ccxt::any url = this->safeString(
                     ::getValue(this->urls, std::string("api")),
                     std::string("ws"));
                 awaitValue(this->connectSxbetCentrifugo(url));
                 ccxt::any client = this->client(url);
                 ccxt::any channel = std::string("best_odds_v3:global");
                 ccxt::any hydrated = false;
                 if (isTrue(isEqual(this->safeValue(this->tickers, sym),
                                    ccxt::any{}))) {
                   // hydrate from the REST snapshot so the first call does not
                   // hang until the market's next top-of-book change - the
                   // channel is global, so the seed must fire for every newly
                   // watched market, not only on a fresh subscription
                   ccxt::any snapshot =
                       awaitValue(this->fetchSxbetBookSnapshot(marketHash));
                   ccxt::any raw = this->parseSxbetSnapshotBestOdds(snapshot);
                   ccxt::any ticker =
                       this->parsePredictionTicker(raw, outcomeObj);
                   ::setValue(this->tickers, sym, ticker);
                   hydrated = true;
                 }
                 ccxt::any requestId = this->requestId(url);
                 this->registerSxbetWsRequest(requestId, messageHash, channel);
                 ccxt::any subscribeMsg = ccxt::dict{
                     {std::string("subscribe"),
                      ccxt::dict{
                          {std::string("channel"), channel},
                      }},
                     {std::string("id"), requestId},
                 };
                 ccxt::any future =
                     this->watch(url, messageHash, subscribeMsg, channel);
                 if (isTrue(hydrated)) {
                   this->resolve(this->safeValue(this->tickers, sym),
                                 messageHash);
                 }
                 ccxt::any tickerResult = awaitValue(future);
                 return tickerResult;
               })
        .share();
  }

  virtual void handleTicker(ccxt::any client, ccxt::any rows) {
    //
    //     {
    //         "marketHash": "0xbf06...16a2eb",
    //         "outcomeOne": { "percentageOdds": "40000000000000000000", "size":
    //         "1000000" }, "outcomeTwo": null
    //     }
    //
    ccxt::any watchedTickers = this->safeDict(
        this->options, std::string("wsWatchedTickers"), ccxt::dict{});
    ccxt::any watchedSyms = getObjectKeys(watchedTickers);
    ccxt::any rowsLength = getArrayLength(rows);
    for (ccxt::any i = 0; isLessThan(i, rowsLength); postFixIncrement(i)) {
      ccxt::any entry = this->safeDict(rows, i);
      ccxt::any marketHash = this->safeString(entry, std::string("marketHash"));
      if (isTrue(isEqual(marketHash, ccxt::any{}))) {
        continue;
      }
      // every publication carries BOTH sides (null = no resting liquidity), so
      // the legacy best-odds shape rebuilds directly without any merge cache
      ccxt::any bestOne =
          this->safeDict(entry, std::string("outcomeOne"), ccxt::dict{});
      ccxt::any bestTwo =
          this->safeDict(entry, std::string("outcomeTwo"), ccxt::dict{});
      ccxt::any raw = ccxt::dict{
          {std::string("marketHash"), marketHash},
          {std::string("outcomeOne"),
           ccxt::dict{
               {std::string("percentageOdds"),
                this->safeString(bestOne, std::string("percentageOdds"))},
           }},
          {std::string("outcomeTwo"),
           ccxt::dict{
               {std::string("percentageOdds"),
                this->safeString(bestTwo, std::string("percentageOdds"))},
           }},
      };
      ccxt::any watchedSymsLength = getArrayLength(watchedSyms);
      for (ccxt::any j = 0; isLessThan(j, watchedSymsLength);
           postFixIncrement(j)) {
        ccxt::any sym = ::getValue(watchedSyms, j);
        if (isTrue(
                !isEqual(this->safeString(watchedTickers, sym), marketHash))) {
          continue;
        }
        ccxt::any outcomeObj = this->outcome(sym);
        ccxt::any ticker = this->parsePredictionTicker(raw, outcomeObj);
        ::setValue(this->tickers, sym, ticker);
        this->resolve(ticker, add(std::string("ticker::"), sym));
      }
    }
  }

  /**
   * @method
   * @name sxbet#watchTrades
   * @description streams public bets of an outcome; the venue channel is
   * global, entries are filtered down to the requested outcome
   * @see https://docs.sx.bet/api-reference/channel-recent-trades-v3
   * @param {string} outcome unified outcome or outcome token id
   * @param {int} [since] timestamp in ms of the earliest trade to return
   * @param {int} [limit] the maximum number of trades to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction trade
   * structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  std::shared_future<ccxt::any>
  watchTrades(ccxt::any outcome, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadOutcome(outcome));
                 ccxt::any outcomeObj = this->outcome(outcome);
                 ccxt::any sym =
                     this->safeString(outcomeObj, std::string("outcome"));
                 ccxt::any messageHash = add(std::string("trades::"), sym);
                 ccxt::any trades = awaitValue(this->subscribeSxbetChannel(
                     messageHash, std::string("recent_trades_v3:global")));
                 return this->filterBySinceLimit(
                     trades, since, limit, std::string("timestamp"), true);
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name sxbet#parseSxbetV3PublicTrade
   * @description parses one recent_trades_v3 publication (public TradeV3 shape)
   * into a unified trade
   * @param {object} trade the raw public trade row
   * @returns {object} a [prediction trade
   * structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  virtual ccxt::any parseSxbetV3PublicTrade(ccxt::any trade) {
    ccxt::any marketHash =
        this->safeString(trade, std::string("marketHash"), std::string(""));
    ccxt::any isBettingOutcomeOne =
        this->safeBool(trade, std::string("isBettingOutcomeOne"), true);
    ccxt::any outcomeId = ccxt::any{};
    if (isTrue(isBettingOutcomeOne)) {
      outcomeId = marketHash;
    } else {
      outcomeId = (add(marketHash, std::string("-2")));
    }
    ccxt::any outcomeObj = this->safeOutcome(outcomeId);
    ccxt::any oneDenom = std::string("100000000000000000000");
    ccxt::any usdcDecimals = std::string("1000000");
    ccxt::any odds =
        this->safeString(trade, std::string("weightedAverageOdds"));
    ccxt::any price = (isTrue((!isEqual(odds, ccxt::any{})))
                           ? ccxt::any(this->parseNumber(
                                 ccxt::Precise::stringDiv(odds, oneDenom)))
                           : ccxt::any(ccxt::any{}));
    ccxt::any stake =
        this->safeString(trade, std::string("totalStake"), std::string("0"));
    ccxt::any amount =
        this->parseNumber(ccxt::Precise::stringDiv(stake, usdcDecimals, 6));
    ccxt::any timestamp =
        this->parse8601(this->safeString(trade, std::string("betTime")));
    return this->safePredictionTrade(ccxt::dict{
        {std::string("id"), this->safeString(trade, std::string("tradeId"))},
        {std::string("info"), trade},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("outcome"),
         this->safeString(outcomeObj, std::string("outcome"))},
        {std::string("outcomeId"),
         this->safeString(outcomeObj, std::string("outcomeId"), outcomeId)},
        {std::string("label"),
         this->safeString(outcomeObj, std::string("label"))},
        {std::string("market"),
         this->safeString(outcomeObj, std::string("market"))},
        {std::string("order"), ccxt::any{}},
        {std::string("type"), ccxt::any{}},
        {std::string("side"), std::string("buy")},
        {std::string("takerOrMaker"), ccxt::any{}},
        {std::string("price"), price},
        {std::string("amount"), amount},
        {std::string("cost"), amount},
        {std::string("fee"), ccxt::any{}},
    });
  }

  virtual void handleTrades(ccxt::any client, ccxt::any rows) {
    //
    //     { "trade": { "tradeId": "0xac6b...", "marketHash": "0x1fec...",
    //     "isBettingOutcomeOne": true,
    //                  "totalStake": "1000000", "weightedAverageOdds":
    //                  "40000000000000000000", "betTime":
    //                  "2026-07-31T18:22:41.000Z", ... } }
    //
    ccxt::any rowsLength = getArrayLength(rows);
    for (ccxt::any i = 0; isLessThan(i, rowsLength); postFixIncrement(i)) {
      ccxt::any row = this->safeDict(::getValue(rows, i), std::string("trade"),
                                     ::getValue(rows, i));
      ccxt::any trade = this->parseSxbetV3PublicTrade(row);
      ccxt::any sym = this->safeString(trade, std::string("outcome"));
      if (isTrue(isEqual(sym, ccxt::any{}))) {
        continue;
      }
      if (isTrue(isEqual(this->trades, ccxt::any{}))) {
        this->trades = this->createSafeDictionary();
      }
      if (isTrue(isEqual(this->safeValue(this->trades, sym), ccxt::any{}))) {
        ccxt::any tradesLimit =
            this->safeInteger(this->options, std::string("tradesLimit"), 1000);
        ::setValue(this->trades, sym, ccxt::ws::ArrayCache(tradesLimit));
      }
      ccxt::any stored = ::getValue(this->trades, sym);
      ::wsAppend(stored, trade);
      this->resolve(stored, add(std::string("trades::"), sym));
    }
  }

  /**
   * @method
   * @name sxbet#watchMyTrades
   * @description streams the authenticated wallet's fills over its per-account
   * v3 channel
   * @see https://docs.sx.bet/api-reference/channel-fills-v3
   * @param {string} [outcome] unified outcome or outcome token id to narrow the
   * stream down to
   * @param {int} [since] timestamp in ms of the earliest trade to return
   * @param {int} [limit] the maximum number of trades to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction trade
   * structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
   */
  std::shared_future<ccxt::any>
  watchMyTrades(ccxt::any outcome = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->walletAddress, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " watchMyTrades() requires a walletAddress"))));
                 }
                 ccxt::any messageHash = std::string("myTrades");
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   ccxt::any outcomeObj = this->outcome(outcome);
                   ccxt::any sym =
                       this->safeString(outcomeObj, std::string("outcome"));
                   messageHash = add(std::string("myTrades::"), sym);
                 }
                 ccxt::any channel = add(std::string("account:fills_v3_#"),
                                         this->walletAddress);
                 ccxt::any trades = awaitValue(
                     this->subscribeSxbetChannel(messageHash, channel));
                 return this->filterBySinceLimit(
                     trades, since, limit, std::string("timestamp"), true);
               })
        .share();
  }

  virtual void handleMyTrade(ccxt::any client, ccxt::any rows) {
    //
    //     FillV3 rows - identical to GET /fills-v3
    //
    ccxt::any rowsLength = getArrayLength(rows);
    for (ccxt::any i = 0; isLessThan(i, rowsLength); postFixIncrement(i)) {
      ccxt::any row = this->safeDict(::getValue(rows, i), std::string("fill"),
                                     ::getValue(rows, i));
      ccxt::any trade = this->parseSxbetV3Fill(row);
      ccxt::any sym = this->safeString(trade, std::string("outcome"));
      if (isTrue(isEqual(sym, ccxt::any{}))) {
        continue;
      }
      if (isTrue(isEqual(this->myTrades, ccxt::any{}))) {
        ccxt::any myTradesLimit = this->safeInteger(
            this->options, std::string("myTradesLimit"), 1000);
        this->myTrades = ccxt::ws::ArrayCacheByOutcomeById(myTradesLimit);
      }
      ccxt::any stored = this->myTrades;
      ::wsAppend(stored, trade);
      this->resolve(stored, std::string("myTrades"));
      this->resolve(stored, add(std::string("myTrades::"), sym));
    }
  }

  /**
   * @method
   * @name sxbet#watchOrders
   * @description streams updates of the authenticated wallet's orders over its
   * per-account v3 channel
   * @see https://docs.sx.bet/api-reference/channel-orders-v3
   * @param {string} [outcome] unified outcome or outcome token id to narrow the
   * stream down to
   * @param {int} [since] timestamp in ms of the earliest order to return
   * @param {int} [limit] the maximum number of orders to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [prediction order
   * structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
   */
  std::shared_future<ccxt::any>
  watchOrders(ccxt::any outcome = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->walletAddress, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " watchOrders() requires a walletAddress"))));
                 }
                 ccxt::any messageHash = std::string("orders");
                 if (isTrue(!isEqual(outcome, ccxt::any{}))) {
                   awaitValue(this->loadOutcome(outcome));
                   ccxt::any outcomeObj = this->outcome(outcome);
                   ccxt::any sym =
                       this->safeString(outcomeObj, std::string("outcome"));
                   messageHash = add(std::string("orders::"), sym);
                 }
                 ccxt::any channel = add(std::string("account:orders_v3_#"),
                                         this->walletAddress);
                 ccxt::any orders = awaitValue(
                     this->subscribeSxbetChannel(messageHash, channel));
                 return this->filterBySinceLimit(
                     orders, since, limit, std::string("timestamp"), true);
               })
        .share();
  }

  virtual void handleOrder(ccxt::any client, ccxt::any rows) {
    //
    //     OrderV3 rows - identical to GET /orders-v3 (plus INACTIVE states with
    //     inactiveReason)
    //
    ccxt::any rowsLength = getArrayLength(rows);
    for (ccxt::any i = 0; isLessThan(i, rowsLength); postFixIncrement(i)) {
      ccxt::any row = this->safeDict(::getValue(rows, i), std::string("order"),
                                     ::getValue(rows, i));
      ccxt::any order = this->parsePredictionOrder(row);
      if (isTrue(isEqual(this->orders, ccxt::any{}))) {
        ccxt::any cacheLimit =
            this->safeInteger(this->options, std::string("ordersLimit"), 1000);
        this->orders = ccxt::ws::ArrayCacheByOutcomeById(cacheLimit);
      }
      ccxt::any stored = this->orders;
      ::wsAppend(stored, order);
      this->resolve(stored, std::string("orders"));
      ccxt::any sym = this->safeString(order, std::string("outcome"));
      if (isTrue(!isEqual(sym, ccxt::any{}))) {
        this->resolve(stored, add(std::string("orders::"), sym));
      }
    }
  }

  ccxt::any handleErrors(ccxt::any code, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    // sx.bet returns { "error": "Bad Request", "message": <code or [strings]>,
    // "statusCode": 4xx }; map the known codes to ccxt errors so callers can
    // distinguish a rejected order or a validation problem from a transport
    // outage (the base otherwise maps a bare 4xx to the exchange-not-available
    // error). unmapped codes fall through to the base http-status handling
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    ccxt::any message = this->safeValue(response, std::string("message"));
    if (isTrue(isEqual(message, ccxt::any{}))) {
      return ccxt::any{};
    }
    // validation failures arrive in string-array form, business errors in
    // single-code-string form
    ccxt::any messageString = ccxt::any{};
    if (isTrue(isArray(message))) {
      messageString = join(message, std::string(", "));
    } else {
      messageString = message;
    }
    ccxt::any feedback = add(add(this->id, std::string(" ")), body);
    this->throwExactlyMatchedException(
        ::getValue(this->exceptions, std::string("exact")), messageString,
        feedback);
    this->throwBroadlyMatchedException(
        ::getValue(this->exceptions, std::string("broad")), messageString,
        feedback);
    // a 400 is a client-side bad request (bad params, invalid order), not a
    // transport outage — throw BadRequest instead of letting the base map the
    // bare 400 to a retryable network-unavailable error
    if (isTrue(isEqual(code, 400))) {
      throw BadRequest(toString(feedback));
    }
    return ccxt::any{};
  }

  /**
   * @ignore
   * @method
   * @name sxbet#sign
   * @description builds the request url and attaches the x-sx-api-key header;
   * every private v3 route authenticates with the apiKey credential, so its
   * absence fails fast instead of surfacing a raw 401
   * @param {string} path the endpoint path
   * @param {string|string[]} api the api group and access level
   * @param {string} method the http method
   * @param {object} params the request parameters
   * @param {object} [headers] request headers
   * @param {string} [body] the request body
   * @returns {object} a dict with url, method, body and headers
   */
  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("sxbet"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any apiGroup =
        (isTrue(isString(api)) ? ccxt::any(api)
                               : ccxt::any(::getValue(api, 0)));
    ccxt::any accessLevel =
        (isTrue(isString(api)) ? ccxt::any(std::string("public"))
                               : ccxt::any(::getValue(api, 1)));
    if (isTrue(isTrue((isEqual(accessLevel, std::string("private")))) &&
               isTrue((isEqual(this->apiKey, ccxt::any{}))))) {
      throw AuthenticationError(toString(
          add(add(add(this->id, std::string(" ")), path),
              std::string(" is a private endpoint and requires the apiKey "
                          "credential (the x-sx-api-key header)"))));
    }
    ccxt::any baseUrls = ::getValue(this->urls, std::string("api"));
    ccxt::any baseUrl = this->safeString(
        baseUrls, apiGroup, ::getValue(baseUrls, std::string("sxbet")));
    ccxt::any url =
        add(add(baseUrl, std::string("/")), this->implodeParams(path, params));
    ccxt::any query = this->omit(params, this->extractParams(path));
    ccxt::any existingHeaders =
        (isTrue((!isEqual(headers, ccxt::any{}))) ? ccxt::any(headers)
                                                  : ccxt::any(ccxt::dict{}));
    ccxt::any headersExtended = this->extend(
        ccxt::dict{
            {std::string("Accept"), std::string("application/json")},
            {std::string("Content-Type"), std::string("application/json")},
        },
        existingHeaders);
    if (isTrue(!isEqual(this->apiKey, ccxt::any{}))) {
      ::setValue(headersExtended, std::string("x-sx-api-key"), this->apiKey);
    }
    // DELETE /orders-v3 carries its order ids in a JSON body; the other DELETE
    // routes - /orders-v3/all and /orders-v3/event - take query parameters,
    // like every GET
    ccxt::any sendAsQuery = (isEqual(method, std::string("GET")));
    if (isTrue(isEqual(method, std::string("DELETE")))) {
      ccxt::any hasOrdersList = (inOp(query, std::string("orders")));
      sendAsQuery = !isTrue(hasOrdersList);
    }
    ccxt::any bodyValue = body;
    if (isTrue(sendAsQuery)) {
      ccxt::any querystring = this->urlencode(query);
      if (isTrue(!isEqual(querystring, std::string("")))) {
        url = add(url, add(std::string("?"), querystring));
      }
    } else {
      ccxt::any queryKeys = getObjectKeys(query);
      ccxt::any queryKeysLength = getArrayLength(queryKeys);
      if (isTrue(isGreaterThan(queryKeysLength, 0))) {
        bodyValue = this->json(query);
      }
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), bodyValue},
        {std::string("headers"), headersExtended},
    };
  }
